action.command:
cd /workspace && python3 - <<'EOF'
import json
d=json.load(open('contracts/openapi.contract.json'))
paths=d['paths']
out={}
for p,v in paths.items():
    for m,op in v.items():
        rb = op.get('requestBody')
        out[f"{m.upper()} {p}"] = {
            'operationId': op.get('operationId'),
            'hasRequestBody': bool(rb),
        }
with open('/tmp/summary.json','w') as f:
    json.dump(out,f,indent=2)
EOF
cat /tmp/summary.json

