package server

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

type ctxKey string

const ctxUserKey ctxKey = "user"

type AuthUser struct {
	UserID     string
	Username   string
	Roles      []string
	ActiveRole string
	Token      string
}

func generateToken() string {
	b := make([]byte, 24)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func (s *Server) createSession(ctx context.Context, userID string, roles []string) (string, bool, error) {
	token := generateToken()
	roleSelectionRequired := true
	var activeRole *string
	if len(roles) == 1 {
		roleSelectionRequired = false
		activeRole = &roles[0]
	}
	_, err := s.DB.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role, role_selection_required, created_at, expires_at)
		VALUES ($1,$2,$3,$4, now(), now() + interval '24 hours')`, token, userID, activeRole, roleSelectionRequired)
	if err != nil {
		return "", false, err
	}
	return token, roleSelectionRequired, nil
}

func (s *Server) resolveSession(ctx context.Context, token string) (*AuthUser, error) {
	var userID, username string
	var roles []string
	var activeRole *string
	var active bool
	row := s.DB.QueryRow(ctx, `SELECT u.id, u.username, u.roles, s.active_role, u.active
		FROM sessions s JOIN users u ON u.id = s.user_id
		WHERE s.token = $1 AND (s.expires_at IS NULL OR s.expires_at > now())`, token)
	if err := row.Scan(&userID, &username, &roles, &activeRole, &active); err != nil {
		return nil, err
	}
	if !active {
		return nil, pgx.ErrNoRows
	}
	au := &AuthUser{UserID: userID, Username: username, Roles: roles, Token: token}
	if activeRole != nil {
		au.ActiveRole = *activeRole
	}
	return au, nil
}

// AuthMiddleware extracts bearer [REDACTED], resolves session, and stores AuthUser in context.
// Endpoints requiring auth call RequireAuth() to fetch it.
func (s *Server) AuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authz := r.Header.Get("Authorization")
		if strings.HasPrefix(authz, "Bearer ") {
			token := strings.TrimPrefix(authz, "Bearer ")
			if au, err := s.resolveSession(r.Context(), token); err == nil {
				ctx := context.WithValue(r.Context(), ctxUserKey, au)
				r = r.WithContext(ctx)
			}
		}
		next.ServeHTTP(w, r)
	})
}

func UserFromContext(r *http.Request) *AuthUser {
	v := r.Context().Value(ctxUserKey)
	if v == nil {
		return nil
	}
	return v.(*AuthUser)
}

func touchSessionExpiry(ctx context.Context, db interface{ Exec(context.Context, string, ...interface{}) (interface{}, error) }) {}

var _ = time.Now

