package server

import "net/http"

const (
	RoleAdministrator        = "administrator"
	RoleDispatcher           = "dispatcher"
	RoleRequester            = "requester"
	RoleCollectionProf       = "collection_professional"
	RoleDeliveryPartner      = "delivery_partner"
	RoleNodeHandler          = "node_handler"
	RoleLaboratoryTeam       = "laboratory_team"
)

func contains(list []string, v string) bool {
	for _, x := range list {
		if x == v {
			return true
		}
	}
	return false
}

// RequireAuth returns the authenticated user or writes 401 and returns nil.
func RequireAuth(w http.ResponseWriter, r *http.Request) *AuthUser {
	u := UserFromContext(r)
	if u == nil {
		WriteErr(w, http.StatusUnauthorized, "unauthorized", "authentication required")
		return nil
	}
	return u
}

// RequireRole ensures the user's ACTIVE role is one of allowed. Administrator
// is always allowed unless explicitly excluded via allowAdminOverride=false semantics
// (administrator can do everything dispatcher can do, handled by callers including
// RoleDispatcher in the allowed set when appropriate).
func RequireRole(w http.ResponseWriter, r *http.Request, allowed ...string) *AuthUser {
	u := RequireAuth(w, r)
	if u == nil {
		return nil
	}
	if u.ActiveRole == "" {
		WriteErr(w, http.StatusConflict, "role_not_selected", "an active role must be selected")
		return nil
	}
	if contains(allowed, u.ActiveRole) {
		return u
	}
	WriteErr(w, http.StatusForbidden, "forbidden", "role not permitted for this action")
	return nil
}

