package server

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
)

type CapacityRow struct {
	CapacityUnits       int
	ReservedUnits       int
	AvailableUnits      int
	CooledCapacityUnits int
	CooledReservedUnits int
	CooledAvailable     int
}

func (s *Server) getOrCreateCapacity(ctx context.Context, resourceType, resourceID string) (CapacityRow, error) {
	var c CapacityRow
	row := s.DB.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM capacities WHERE resource_type=$1 AND resource_id=$2`, resourceType, resourceID)
	err := row.Scan(&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits)
	if errors.Is(err, pgx.ErrNoRows) {
		_, err2 := s.DB.Exec(ctx, `INSERT INTO capacities (resource_type, resource_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
			VALUES ($1,$2,0,0,0,0) ON CONFLICT DO NOTHING`, resourceType, resourceID)
		if err2 != nil {
			return c, err2
		}
		return CapacityRow{}, nil
	}
	if err != nil {
		return c, err
	}
	c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
	c.CooledAvailable = c.CooledCapacityUnits - c.CooledReservedUnits
	return c, nil
}

// reserveCapacity attempts to reserve 1 unit (regular or cooled) atomically; returns ok.
func (s *Server) reserveCapacity(ctx context.Context, resourceType, resourceID string, cooled bool, units int) (bool, error) {
	if units <= 0 {
		units = 1
	}
	var sql string
	if cooled {
		sql = `UPDATE capacities SET reserved_units = reserved_units,
			cooled_reserved_units = cooled_reserved_units + $3
			WHERE resource_type=$1 AND resource_id=$2 AND (cooled_capacity_units - cooled_reserved_units) >= $3`
	} else {
		sql = `UPDATE capacities SET reserved_units = reserved_units + $3
			WHERE resource_type=$1 AND resource_id=$2 AND (capacity_units - reserved_units) >= $3`
	}
	tag, err := s.DB.Exec(ctx, sql, resourceType, resourceID, units)
	if err != nil {
		return false, err
	}
	return tag.RowsAffected() > 0, nil
}

func (s *Server) releaseCapacity(ctx context.Context, resourceType, resourceID string, cooled bool, units int) error {
	if units <= 0 {
		units = 1
	}
	var sql string
	if cooled {
		sql = `UPDATE capacities SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - $3)
			WHERE resource_type=$1 AND resource_id=$2`
	} else {
		sql = `UPDATE capacities SET reserved_units = GREATEST(0, reserved_units - $3)
			WHERE resource_type=$1 AND resource_id=$2`
	}
	_, err := s.DB.Exec(ctx, sql, resourceType, resourceID, units)
	return err
}

