package server

import (
	"net/http"

	"github.com/google/uuid"
)

type coordinateReq struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type createLocationReq struct {
	Name            string         `json:"name"`
	Coordinate      coordinateReq  `json:"coordinate"`
	CoverageKm      *float64       `json:"coverageKm"`
	HandlingMinutes *int           `json:"handlingMinutes"`
	Active          *bool          `json:"active"`
	Functions       []string       `json:"functions"`
}

func funcFlags(functions []string) (cp, tp, hub, lab bool) {
	for _, f := range functions {
		switch f {
		case "collection_point":
			cp = true
		case "transfer_point":
			tp = true
		case "hub":
			hub = true
		case "laboratory":
			lab = true
		}
	}
	return
}

func locationToMap(id, name string, lat, lon, coverage float64, handling int, active bool, cp, tp, hub, lab bool) map[string]interface{} {
	return map[string]interface{}{
