		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.bumpNetworkRevision(r.Context())
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "create_connection", "connection", id, true, nil)
	WriteData(w, http.StatusCreated, map[string]interface{}{
		"connectionId": id, "fromLocationId": req.FromLocationID, "toLocationId": req.ToLocationID,
		"travelMinutes": req.TravelMinutes, "costUnits": req.CostUnits, "cooled": cooled, "active": active,
	})
}

type setConnectionStatusReq struct {
	ConnectionID string `json:"connectionId"`
	Active       *bool  `json:"active"`
}

func (s *Server) HandleSetConnectionStatus(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleAdministrator)
	if u == nil {
		return
	}
	var req setConnectionStatusReq
	if !DecodeJSON(w, r, &req) || req.Active == nil || req.ConnectionID == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "connectionId and active required")
		return
	}
	tag, err := s.DB.Exec(r.Context(), `UPDATE connections SET active=$1 WHERE id=$2`, *req.Active, req.ConnectionID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if tag.RowsAffected() == 0 {
		WriteErr(w, http.StatusNotFound, "not_found", "connection not found")
		return
	}
	s.bumpNetworkRevision(r.Context())
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "set_connection_status", "connection", req.ConnectionID, true, map[string]interface{}{"active": *req.Active})
	WriteData(w, http.StatusOK, map[string]interface{}{"connectionId": req.ConnectionID, "active": *req.Active})
}

func (s *Server) bumpNetworkRevision(ctx context.Context) {
	_, _ = s.DB.Exec(ctx, `UPDATE network_revision SET revision = revision + 1 WHERE id = 1`)
	go s.recomputeServiceability(context.Background())
}

