	rows, err := s.DB.Query(ctx, `SELECT laboratory_id FROM laboratory_acceptance WHERE sample_type_id=$1 AND accepts=true`, sampleTypeID)
	if err != nil {
		return ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory"}
	}
	var labIDs []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err == nil {
			labIDs = append(labIDs, id)
		}
	}
	rows.Close()
	if len(labIDs) == 0 {
		return ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory"}
	}

	activeLabSet := map[string]bool{}
	for _, l := range locs {
		if l.IsLaboratory && l.Active {
			activeLabSet[l.ID] = true
		}
	}

	bestArrival := time.Time{}
	bestLab := ""
	found := false
	for _, labID := range labIDs {
		if !activeLabSet[labID] {
			continue
		}
