cd /workspace && python3 -c "
import json
d=json.load(open('contracts/openapi.contract.json'))
def simplify_schema(s, depth=0):
    if not isinstance(s, dict):
        return s
    if '\$ref' in s:
        return 'REF:'+s['\$ref']
    t = s.get('type')
    if t == 'object':
        props = s.get('properties', {})
        req = set(s.get('required', []))
        out = {}
        for k,v in props.items():
            mark = '*' if k in req else ''
            out[k+mark] = simplify_schema(v, depth+1)
        return out
    elif t == 'array':
        return [simplify_schema(s.get('items', {}), depth+1)]
    else:
        parts=[t]
        if 'format' in s: parts.append(s['format'])
        if 'enum' in s: parts.append('enum:'+','.join(map(str,s['enum'])))
        return '|'.join(str(p) for p in parts if p)
out={}
for name,schema in d['components']['schemas'].items():
    out[name]=simplify_schema(schema)
json.dump(out, open('/tmp/schemas.json','w'), indent=2)
print('ok')
"
cat /tmp/schemas.json

