package server

import "net/http"

type configureCapacityReq struct {
	ResourceID          string `json:"resourceId"`
	CapacityUnits       *int   `json:"capacityUnits"`
	CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
}

func (s *Server) HandleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleAdministrator, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req configureCapacityReq
	if !DecodeJSON(w, r, &req) || req.ResourceID == "" || req.CapacityUnits == nil {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "resourceId, capacityUnits required")
		return
	}
	if u.ActiveRole != RoleAdministrator {
		var assigned *string
		_ = s.DB.QueryRow(r.Context(), `SELECT assigned_location_id FROM users WHERE id=$1`, u.UserID).Scan(&assigned)
		if assigned == nil || *assigned != req.ResourceID {
			WriteErr(w, http.StatusForbidden, "forbidden", "not assigned to this resource")
			return
		}
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	// resource type: location. either connection or location; look up in both.
	resType := "location"
	var exists bool
	_ = s.DB.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, req.ResourceID).Scan(&exists)
	if !exists {
		_ = s.DB.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM connections WHERE id=$1)`, req.ResourceID).Scan(&exists)
		if exists {
			resType = "connection"
		}
	}
	if !exists {
		WriteErr(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	_, err := s.DB.Exec(r.Context(), `INSERT INTO capacities (resource_type, resource_id, capacity_units, cooled_capacity_units)
		VALUES ($1,$2,$3,$4)
		ON CONFLICT (resource_type, resource_id) DO UPDATE SET capacity_units=$3, cooled_capacity_units=$4`,
		resType, req.ResourceID, *req.CapacityUnits, cooled)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.bumpNetworkRevision(r.Context())
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "configure_capacity", resType, req.ResourceID, true, map[string]interface{}{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
	WriteData(w, http.StatusOK, map[string]interface{}{"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
}

type setWorkerAvailabilityReq struct {
	WorkerID      string `json:"workerId"`
	Available     *bool  `json:"available"`
	CapacityUnits *int   `json:"capacityUnits"`
}

func (s *Server) HandleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleAdministrator, RoleDispatcher)
	if u == nil {
		return
	}
	var req setWorkerAvailabilityReq
	if !DecodeJSON(w, r, &req) || req.Available == nil || req.WorkerID == "" || req.CapacityUnits == nil {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "workerId, available, capacityUnits required")
		return
	}
	tag, err := s.DB.Exec(r.Context(), `UPDATE users SET recent_assignment_count=$1 WHERE id=$2`, *req.CapacityUnits, req.WorkerID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if tag.RowsAffected() == 0 {
		WriteErr(w, http.StatusNotFound, "not_found", "worker not found")
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE users SET active=$1 WHERE id=$2 AND $1=false`, *req.Available, req.WorkerID)
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "set_worker_availability", "user", req.WorkerID, true, map[string]interface{}{"available": *req.Available})
	WriteData(w, http.StatusOK, map[string]interface{}{"workerId": req.WorkerID, "available": *req.Available, "capacityUnits": *req.CapacityUnits})
}

