package server

import (
	"context"

	"github.com/google/uuid"
)

// createAssignment inserts a new assignment row in "pending" status and
// attempts to offer it to the best eligible worker immediately.
func (s *Server) createAssignment(ctx context.Context, journeyID, kind string, sequence int, fromLoc, toLoc, nodeID, labID, sampleID string, expectedSampleTypeID string) (string, error) {
	id := uuid.New().String()
	_, err := s.DB.Exec(ctx, `INSERT INTO assignments (id, journey_id, kind, sequence, status, from_location_id, to_location_id, node_id, laboratory_id, sample_id, expected_sample_type_id)
		VALUES ($1,$2,$3,$4,'pending',$5,$6,$7,$8,$9,$10)`,
		id, journeyID, kind, sequence, nullableUUID(fromLoc), nullableUUID(toLoc), nullableUUID(nodeID), nullableUUID(labID), sampleID, nullableUUID(expectedSampleTypeID))
	if err != nil {
		return "", err
	}
	s.tryOfferAssignment(ctx, id)
	return id, nil
}

func nullableUUID(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

// eligibleWorkersFor returns worker IDs eligible for the given assignment kind,
// ordered by fairness (fewest recent assignments first, then decline priority).
func (s *Server) eligibleWorkersFor(ctx context.Context, kind, nodeOrLabID, requiredQualification string, declined []string) ([]string, error) {
	var query string
	var args []interface{}
	switch kind {
	case "collection":
		query = `SELECT id FROM users WHERE active=true AND 'collection_professional' = ANY(roles)
			AND ($1 = '' OR $1 = ANY(qualifications))
			AND NOT (id = ANY($2::uuid[]))
			ORDER BY (priority_penalty_until IS NOT NULL AND priority_penalty_until > now()) ASC, recent_assignment_count ASC`
		args = []interface{}{requiredQualification, declined}
	case "transport":
		query = `SELECT id FROM users WHERE active=true AND 'delivery_partner' = ANY(roles)
			AND NOT (id = ANY($1::uuid[]))
			ORDER BY (priority_penalty_until IS NOT NULL AND priority_penalty_until > now()) ASC, recent_assignment_count ASC`
		args = []interface{}{declined}
	case "node":
		query = `SELECT id FROM users WHERE active=true AND 'node_handler' = ANY(roles) AND assigned_location_id=$1
			AND NOT (id = ANY($2::uuid[]))
			ORDER BY (priority_penalty_until IS NOT NULL AND priority_penalty_until > now()) ASC, recent_assignment_count ASC`
		args = []interface{}{nodeOrLabID, declined}
	case "laboratory":
		query = `SELECT id FROM users WHERE active=true AND 'laboratory_team' = ANY(roles) AND assigned_location_id=$1
			AND NOT (id = ANY($2::uuid[]))
			ORDER BY (priority_penalty_until IS NOT NULL AND priority_penalty_until > now()) ASC, recent_assignment_count ASC`
		args = []interface{}{nodeOrLabID, declined}
	}
	rows, err := s.DB.Query(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err == nil {
			out = append(out, id)
		}
	}
	return out, nil
}

// tryOfferAssignment offers a pending/re-offerable assignment to the next
// eligible worker who hasn't declined it yet.
func (s *Server) tryOfferAssignment(ctx context.Context, assignmentID string) {
	var kind, status, sampleID string
	var nodeID, labID, expectedType *string
	var declined []string
	row := s.DB.QueryRow(ctx, `SELECT kind, status, sample_id, node_id, laboratory_id, expected_sample_type_id, declined_worker_ids FROM assignments WHERE id=$1`, assignmentID)
	if err := row.Scan(&kind, &status, &sampleID, &nodeID, &labID, &expectedType, &declined); err != nil {
		return
	}
	if status != "pending" {
		return
	}
	requiredQual := ""
	if expectedType != nil {
		_ = s.DB.QueryRow(ctx, `SELECT COALESCE(required_qualification,'') FROM sample_types WHERE id=$1`, *expectedType).Scan(&requiredQual)
	}
	resourceID := ""
	if nodeID != nil {
		resourceID = *nodeID
	} else if labID != nil {
		resourceID = *labID
	}
	candidates, err := s.eligibleWorkersFor(ctx, kind, resourceID, requiredQual, declined)
	if err != nil || len(candidates) == 0 {
		s.Audit(ctx, "system", "dispatcher", "offer_unavailable", "assignment", assignmentID, false, map[string]interface{}{"reason": "no_eligible_worker"})
		return
	}
	worker := candidates[0]
	_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='offered', offered_worker_id=$1, offer_expires_at=now() + interval '5 minutes', updated_at=now() WHERE id=$2`, worker, assignmentID)
	s.Events.Publish(ctx, "assignment.offered", "assignment", assignmentID, map[string]interface{}{"assignmentId": assignmentID, "workerId": worker}, "", &worker)
	s.Audit(ctx, "system", "dispatcher", "offer_assignment", "assignment", assignmentID, true, map[string]interface{}{"workerId": worker})
}

