// planJourneyFromPoint creates only the transport legs needed from startLocID
// onward, for a sample that has already been collected and sealed.
func (s *Server) planJourneyFromPoint(ctx context.Context, sampleID, startLocID, labID, sampleTypeID string) (string, []string, error) {
	conns, err := s.loadActiveConnections(ctx)
	if err != nil {
		return "", nil, err
	}
	var requiresCooled bool
	_ = s.DB.QueryRow(ctx, `SELECT requires_cooled_route FROM sample_types WHERE id=$1`, sampleTypeID).Scan(&requiresCooled)

	if startLocID == "" {
		return "", nil, nil
	}
	pathLocs, pathConns, _ := shortestPath(conns, startLocID, labID, requiresCooled)
	if pathLocs == nil {
		return "", nil, nil
	}
	journeyID := uuid.New().String()
	_, err = s.DB.Exec(ctx, `INSERT INTO journeys (id, plan_version, route_mode, status, sample_ids) VALUES ($1,1,'direct','planned',$2)`,
		journeyID, []string{sampleID})
	if err != nil {
		return "", nil, err
	}
	_, _ = s.DB.Exec(ctx, `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, journeyID, sampleID)

	var assignmentIDs []string
	seq := 1
	for i := 0; i < len(pathConns); i++ {
		fromLoc := pathLocs[i]
		toLoc := pathLocs[i+1]
		isLast := i == len(pathConns)-1
		var nodeID, labIDArg string
		if isLast {
			labIDArg = labID
		} else {
			nodeID = toLoc
		}
		aid, err := s.createAssignment(ctx, journeyID, "transport", seq, fromLoc, toLoc, nodeID, labIDArg, sampleID, sampleTypeID)
		if err != nil {
			return "", nil, err
		}
		assignmentIDs = append(assignmentIDs, aid)
		seq++
	}
	_, _ = s.reserveCapacity(ctx, "location", labID, requiresCooled, 1)
	return journeyID, assignmentIDs, nil
}

