package server

import (
	"net/http"

	"labsample/internal/util"
)

type acceptAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) HandleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req acceptAssignmentReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.AssignmentID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "assignmentId and idempotencyKey required")
		return
	}
	var status string
	var offeredWorker *string
	row := s.DB.QueryRow(r.Context(), `SELECT status, offered_worker_id FROM assignments WHERE id=$1`, req.AssignmentID)
	if err := row.Scan(&status, &offeredWorker); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if status != "offered" {
		WriteErr(w, http.StatusConflict, "offer_not_available", "assignment is not currently offered")
		return
	}
	if offeredWorker == nil || *offeredWorker != u.UserID {
		WriteErr(w, http.StatusForbidden, "ineligible_worker", "assignment was not offered to this worker")
		return
	}
	tag, err := s.DB.Exec(r.Context(), `UPDATE assignments SET status='accepted', worker_id=$1, updated_at=now() WHERE id=$2 AND status='offered'`, u.UserID, req.AssignmentID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if tag.RowsAffected() == 0 {
		WriteErr(w, http.StatusConflict, "offer_not_available", "assignment already resolved")
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE users SET recent_assignment_count = recent_assignment_count + 1 WHERE id=$1`, u.UserID)
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "accept_assignment", "assignment", req.AssignmentID, true, nil)
	WriteData(w, http.StatusCreated, map[string]interface{}{"assignmentId": req.AssignmentID, "workerId": u.UserID, "status": "accepted"})
}

type declineAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	Reason         string `json:"reason"`
	DeclinedAt     string `json:"declinedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) HandleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req declineAssignmentReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.AssignmentID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "assignmentId and idempotencyKey required")
		return
	}
	var status string
	var offeredWorker *string
	row := s.DB.QueryRow(r.Context(), `SELECT status, offered_worker_id FROM assignments WHERE id=$1`, req.AssignmentID)
	if err := row.Scan(&status, &offeredWorker); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if status != "offered" {
		WriteErr(w, http.StatusConflict, "offer_not_available", "assignment is not currently offered")
		return
	}
	if offeredWorker == nil || *offeredWorker != u.UserID {
		WriteErr(w, http.StatusForbidden, "ineligible_worker", "assignment was not offered to this worker")
		return
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE assignments SET status='pending', offered_worker_id=NULL, offer_expires_at=NULL,
		declined_worker_ids = array_append(declined_worker_ids, $1), updated_at=now() WHERE id=$2`, u.UserID, req.AssignmentID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE users SET decline_count = decline_count + 1, priority_penalty_until = now() + interval '30 minutes' WHERE id=$1`, u.UserID)
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})

	s.tryOfferAssignment(r.Context(), req.AssignmentID)
	var reofferedTo *string
	_ = s.DB.QueryRow(r.Context(), `SELECT offered_worker_id FROM assignments WHERE id=$1`, req.AssignmentID).Scan(&reofferedTo)

	resp := map[string]interface{}{
		"assignmentId": req.AssignmentID, "status": "pending", "declinedBy": u.UserID, "declinedAt": util.NowUTC().Format("2006-01-02T15:04:05Z07:00"),
	}
	if reofferedTo != nil {
		resp["reofferedTo"] = *reofferedTo
	}
	WriteData(w, http.StatusCreated, resp)
}

