package server

import (
	"net/http"
	"time"

	"github.com/google/uuid"
	"labsample/internal/util"
)

type collectAndSealReq struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	CollectedAt          string  `json:"collectedAt"`
	ContainerType        string  `json:"containerType"`
	ObservedTemperatureC float64 `json:"observedTemperatureC"`
	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (s *Server) HandleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf)
	if u == nil {
		return
	}
	var req collectAndSealReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" || req.ContainerType == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	var assignedWorker *string
	var kind, astatus string
	row := s.DB.QueryRow(r.Context(), `SELECT worker_id, kind, status FROM assignments WHERE id=$1 AND sample_id=$2`, req.AssignmentID, req.SampleID)
	if err := row.Scan(&assignedWorker, &kind, &astatus); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if kind != "collection" || assignedWorker == nil || *assignedWorker != u.UserID {
		WriteErr(w, http.StatusForbidden, "ineligible_worker", "not assigned to this collection")
		return
	}
	var tmin, tmax float64
	var containerReq string
	_ = s.DB.QueryRow(r.Context(), `SELECT temperature_min_c, temperature_max_c, container_type FROM requests req
		JOIN samples sam ON sam.request_id = req.id WHERE sam.id=$1`, req.SampleID).Scan(&tmin, &tmax, &containerReq)
	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax && req.ContainerType == containerReq

	collectedAt, err := util.ParseTime(req.CollectedAt)
	if err != nil {
		collectedAt = util.NowUTC()
	}

	status := "sealed"
	var exceptionJSON interface{}
	if !compliant {
		status = "exception"
		exceptionJSON = map[string]interface{}{"reason": "handling_out_of_range", "observedTemperatureC": req.ObservedTemperatureC, "containerType": req.ContainerType}
	}

	_, err = s.DB.Exec(r.Context(), `UPDATE samples SET status=$1, sealed=true, sealed_at=$2, current_holder_id=$3, exception=$4, updated_at=now() WHERE id=$5`,
		status, collectedAt, u.UserID, marshalOrEmptyArray(exceptionJSON), req.SampleID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, req.AssignmentID)
	_, _ = s.DB.Exec(r.Context(), `INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, compliant, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)`, req.SampleID, req.AssignmentID, req.ContainerType, req.ObservedTemperatureC, compliant, collectedAt)

	s.Audit(r.Context(), u.UserID, u.ActiveRole, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	s.Events.Publish(r.Context(), "sample.sealed", "sample", req.SampleID, map[string]interface{}{"sampleId": req.SampleID, "status": status}, "dispatcher", nil)

	WriteData(w, http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "status": "sealed", "currentHolderId": u.UserID,
		"sealedAt": collectedAt.Format(time.RFC3339), "handlingCompliant": compliant,
	})
}

type initiateHandoffReq struct {
	SampleID        string `json:"sampleId"`
	FromAssignmentID string `json:"fromAssignmentId"`
	ToAssignmentID   string `json:"toAssignmentId"`
	ReceiverID       string `json:"receiverId"`
	InitiatedAt      string `json:"initiatedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (s *Server) HandleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req initiateHandoffReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.SampleID == "" || req.ReceiverID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	var currentHolder *string
	if err := s.DB.QueryRow(r.Context(), `SELECT current_holder_id FROM samples WHERE id=$1`, req.SampleID).Scan(&currentHolder); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if currentHolder == nil || *currentHolder != u.UserID {
		WriteErr(w, http.StatusForbidden, "forbidden", "not current holder of sample")
		return
	}
	id := uuid.New().String()
	_, err := s.DB.Exec(r.Context(), `INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status)
		VALUES ($1,$2,$3,$4,$5,$6,'pending')`, id, req.SampleID, nullableUUID(req.FromAssignmentID), nullableUUID(req.ToAssignmentID), u.UserID, req.ReceiverID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET pending_handoff_id=$1, updated_at=now() WHERE id=$2`, id, req.SampleID)
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "initiate_handoff", "handoff", id, true, map[string]interface{}{"sampleId": req.SampleID, "receiverId": req.ReceiverID})
	WriteData(w, http.StatusCreated, map[string]interface{}{
		"handoffId": id, "senderId": u.UserID, "receiverId": req.ReceiverID, "currentHolderId": u.UserID, "status": "pending",
	})
}

type confirmHandoffReq struct {
	HandoffID        string `json:"handoffId"`
	ConfirmationSide string `json:"confirmationSide"`
	ConfirmedAt      string `json:"confirmedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (s *Server) HandleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req confirmHandoffReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.HandoffID == "" || req.ConfirmationSide == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "confirmationSide must be sender or receiver")
		return
	}
	var senderID, receiverID, sampleID, status string
	var senderConfirmed, receiverConfirmed bool
	var toAssignment *string
	row := s.DB.QueryRow(r.Context(), `SELECT sender_id, receiver_id, sample_id, status, sender_confirmed, receiver_confirmed, to_assignment_id FROM handoffs WHERE id=$1`, req.HandoffID)
	if err := row.Scan(&senderID, &receiverID, &sampleID, &status, &senderConfirmed, &receiverConfirmed, &toAssignment); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	if req.ConfirmationSide == "sender" && u.UserID != senderID {
		WriteErr(w, http.StatusForbidden, "forbidden", "not the sender")
		return
	}
	if req.ConfirmationSide == "receiver" && u.UserID != receiverID {
		WriteErr(w, http.StatusForbidden, "forbidden", "not the receiver")
		return
	}
	if req.ConfirmationSide == "sender" {
		senderConfirmed = true
	} else {
		receiverConfirmed = true
	}
	newStatus := "pending"
	var currentHolder = senderID
	if senderConfirmed && receiverConfirmed {
		newStatus = "confirmed"
		currentHolder = receiverID
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE handoffs SET sender_confirmed=$1, receiver_confirmed=$2, status=$3, confirmed_at=CASE WHEN $3='confirmed' THEN now() ELSE confirmed_at END WHERE id=$4`,
		senderConfirmed, receiverConfirmed, newStatus, req.HandoffID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	if newStatus == "confirmed" {
		_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET current_holder_id=$1, pending_handoff_id=NULL, updated_at=now() WHERE id=$2`, receiverID, sampleID)
		if toAssignment != nil {
			_, _ = s.DB.Exec(r.Context(), `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, *toAssignment)
		}
		s.Events.Publish(r.Context(), "sample.custody_transferred", "sample", sampleID, map[string]interface{}{"sampleId": sampleID, "currentHolderId": receiverID}, "dispatcher", nil)
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide, "status": newStatus})

	WriteData(w, http.StatusCreated, map[string]interface{}{
		"handoffId": req.HandoffID, "status": newStatus, "senderConfirmed": senderConfirmed, "receiverConfirmed": receiverConfirmed, "currentHolderId": currentHolder,
	})
}

type confirmLabReceiptReq struct {
	SampleID       string `json:"sampleId"`
	LaboratoryID   string `json:"laboratoryId"`
	ReceivedAt     string `json:"receivedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) HandleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req confirmLabReceiptReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.SampleID == "" || req.LaboratoryID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	var assigned *string
	_ = s.DB.QueryRow(r.Context(), `SELECT assigned_location_id FROM users WHERE id=$1`, u.UserID).Scan(&assigned)
	if assigned == nil || *assigned != req.LaboratoryID {
		WriteErr(w, http.StatusForbidden, "forbidden", "not assigned to this laboratory")
		return
	}
	receivedAt, err := util.ParseTime(req.ReceivedAt)
	if err != nil {
		receivedAt = util.NowUTC()
	}
	_, err = s.DB.Exec(r.Context(), `UPDATE samples SET status='received', received_laboratory_id=$1, received_at=$2, current_holder_id=$3, updated_at=now() WHERE id=$4`,
		req.LaboratoryID, receivedAt, u.UserID, req.SampleID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE journeys SET status='completed', updated_at=now() WHERE id=(SELECT active_journey_id FROM samples WHERE id=$1)`, req.SampleID)
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "confirm_laboratory_receipt", "sample", req.SampleID, true, nil)
	s.Events.Publish(r.Context(), "sample.received", "sample", req.SampleID, map[string]interface{}{"sampleId": req.SampleID, "laboratoryId": req.LaboratoryID}, "dispatcher", nil)

	WriteData(w, http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "laboratoryId": req.LaboratoryID, "status": "received", "receivedAt": receivedAt.Format(time.RFC3339),
	})
}

type recordLabExceptionReq struct {
	SampleID       string `json:"sampleId"`
	LaboratoryID   string `json:"laboratoryId"`
	Reason         string `json:"reason"`
	ObservedAt     string `json:"observedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) HandleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req recordLabExceptionReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.SampleID == "" || req.LaboratoryID == "" || req.Reason == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	id := uuid.New().String()
	_, err := s.DB.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$1, updated_at=now() WHERE id=$2`,
		marshalOrEmptyArray(map[string]interface{}{"exceptionId": id, "reason": req.Reason, "laboratoryId": req.LaboratoryID}), req.SampleID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "record_laboratory_exception", "sample", req.SampleID, true, map[string]interface{}{"reason": req.Reason})
	s.Events.Publish(r.Context(), "sample.exception", "sample", req.SampleID, map[string]interface{}{"sampleId": req.SampleID, "reason": req.Reason}, "dispatcher", nil)

	WriteData(w, http.StatusCreated, map[string]interface{}{"exceptionId": id, "sampleId": req.SampleID, "status": "exception", "reason": req.Reason})
}

type recordCheckpointReq struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	LocationID           string  `json:"locationId"`
	ContainerType        string  `json:"containerType"`
	ObservedTemperatureC float64 `json:"observedTemperatureC"`
	RecordedAt           string  `json:"recordedAt"`
	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (s *Server) HandleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req recordCheckpointReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.ContainerType == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "missing required fields")
		return
	}
	var currentHolder *string
	_ = s.DB.QueryRow(r.Context(), `SELECT current_holder_id FROM samples WHERE id=$1`, req.SampleID).Scan(&currentHolder)
	if currentHolder == nil || *currentHolder != u.UserID {
		WriteErr(w, http.StatusForbidden, "forbidden", "not current holder of sample")
		return
	}
	var tmin, tmax float64
	var containerReq string
	_ = s.DB.QueryRow(r.Context(), `SELECT temperature_min_c, temperature_max_c, container_type FROM requests req
		JOIN samples sam ON sam.request_id = req.id WHERE sam.id=$1`, req.SampleID).Scan(&tmin, &tmax, &containerReq)
	compliant := req.ObservedTemperatureC >= tmin && req.ObservedTemperatureC <= tmax && req.ContainerType == containerReq

	recordedAt, err := util.ParseTime(req.RecordedAt)
	if err != nil {
		recordedAt = util.NowUTC()
	}
	id := uuid.New().String()
	_, err = s.DB.Exec(r.Context(), `INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, id, req.SampleID, req.AssignmentID, nullableUUID(req.LocationID), req.ContainerType, req.ObservedTemperatureC, compliant, recordedAt)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	sampleStatus := "in_transit"
	if !compliant {
		sampleStatus = "exception"
		_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET status='exception', exception=$1, updated_at=now() WHERE id=$2`,
			marshalOrEmptyArray(map[string]interface{}{"reason": "handling_out_of_range", "observedTemperatureC": req.ObservedTemperatureC, "containerType": req.ContainerType}), req.SampleID)
	} else {
		_ = s.DB.QueryRow(r.Context(), `SELECT status FROM samples WHERE id=$1`, req.SampleID).Scan(&sampleStatus)
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	WriteData(w, http.StatusCreated, map[string]interface{}{"checkpointId": id, "sampleId": req.SampleID, "compliant": compliant, "sampleStatus": sampleStatus})
}

