)

type recordWorkerLocationReq struct {
	AssignmentID string        `json:"assignmentId"`
	Coordinate   coordinateReq `json:"coordinate"`
	Sequence     int           `json:"sequence"`
	RecordedAt   string        `json:"recordedAt"`
}

func (s *Server) HandleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleCollectionProf, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)
	if u == nil {
		return
	}
	var req recordWorkerLocationReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.AssignmentID == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "assignmentId required")
		return
	}
	recordedAt, err := util.ParseTime(req.RecordedAt)
	if err != nil {
		recordedAt = util.NowUTC()
	}
	_, err = s.DB.Exec(r.Context(), `INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)`, u.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, recordedAt)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	var sampleID string
	_ = s.DB.QueryRow(r.Context(), `SELECT sample_id FROM assignments WHERE id=$1`, req.AssignmentID).Scan(&sampleID)
	if sampleID != "" {
		_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET latest_lat=$1, latest_lon=$2, location_recorded_at=$3, updated_at=now() WHERE id=$4`,
			req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, sampleID)
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "record_worker_location", "assignment", req.AssignmentID, true, nil)
	s.Events.Publish(r.Context(), "worker.location", "user", u.UserID, map[string]interface{}{
		"workerId": u.UserID, "coordinate": map[string]interface{}{"latitude": req.Coordinate.Latitude, "longitude": req.Coordinate.Longitude},
	}, "dispatcher", nil)

	WriteData(w, http.StatusCreated, map[string]interface{}{
