package server

import (
	"net/http"
)

type journeyIDPlanReq struct {
	JourneyID            string `json:"journeyId"`
	ExpectedPlanVersion  int    `json:"expectedPlanVersion"`
	Reason               string `json:"reason"`
	IdempotencyKey       string `json:"idempotencyKey"`
}

func (s *Server) checkPlanVersion(journeyID string, expected int) (int, bool, string, error) {
	var version int
	var status string
	err := s.DB.QueryRow(nil, ``).Scan()
	_ = err
	return version, status == "active", status, nil
}

func (s *Server) HandleCancelJourney(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req journeyIDPlanReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "journeyId and idempotencyKey required")
		return
	}
	var version int
	var status string
	var sampleIDs []string
	row := s.DB.QueryRow(r.Context(), `SELECT plan_version, status, sample_ids FROM journeys WHERE id=$1`, req.JourneyID)
	if err := row.Scan(&version, &status, &sampleIDs); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if version != req.ExpectedPlanVersion {
		WriteErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	if status == "completed" || status == "cancelled" {
		WriteErr(w, http.StatusConflict, "inactive_plan", "journey is not active")
		return
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, req.JourneyID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	_, _ = s.DB.Exec(r.Context(), `UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	for _, sid := range sampleIDs {
		_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET status='cancelled', active_journey_id=NULL, updated_at=now() WHERE id=$1`, sid)
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})
	WriteData(w, http.StatusCreated, map[string]interface{}{"journeyId": req.JourneyID, "status": "cancelled", "sampleIds": sampleIDs})
}

type readJourneyPlanReq struct {
	JourneyID string `json:"journeyId"`
}

func (s *Server) HandleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	u := RequireAuth(w, r)
	if u == nil {
		return
	}
	var req readJourneyPlanReq
	if !DecodeJSON(w, r, &req) || req.JourneyID == "" {
		WriteErr(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	var parentID *string
	var planVersion int
	var routeMode, status string
	var estimatedDelivery *timeT
	var totalCost float64
	var capUsed, capAvail int
	var sampleIDs []string
	row := s.DB.QueryRow(r.Context(), `SELECT parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, sample_ids
		FROM journeys WHERE id=$1`, req.JourneyID)
	if err := row.Scan(&parentID, &planVersion, &routeMode, &status, &estimatedDelivery, &totalCost, &capUsed, &capAvail, &sampleIDs); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}

	legs := s.loadLegs(r.Context(), req.JourneyID)
	stops := s.loadStops(r.Context(), req.JourneyID)

	resp := map[string]interface{}{
		"journeyId": req.JourneyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
		"totalCostUnits": totalCost, "capacityUsed": capUsed, "capacityAvailable": capAvail,
		"sampleIds": sampleIDs, "orderedStops": stops, "legs": legs, "valid": status != "invalid",
	}
	if parentID != nil {
		resp["parentJourneyId"] = *parentID
	}
	if estimatedDelivery != nil {
		resp["estimatedDeliveryAt"] = estimatedDelivery.Format(rfc3339)
	}
	WriteData(w, http.StatusOK, resp)
}

func (s *Server) loadLegs(ctx httpCtx, journeyID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var id, status, sampleID string
		var seq int
		var fromLoc, toLoc, workerID *string
		if rows.Scan(&id, &seq, &status, &fromLoc, &toLoc, &workerID, &sampleID) != nil {
			continue
		}
		leg := map[string]interface{}{"assignmentId": id, "sequence": seq, "status": status, "sampleId": sampleID}
		if fromLoc != nil {
			leg["fromLocationId"] = *fromLoc
		}
		if toLoc != nil {
			leg["toLocationId"] = *toLoc
		}
		if workerID != nil {
			leg["workerId"] = *workerID
		}
		out = append(out, leg)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out
}

func (s *Server) loadStops(ctx httpCtx, journeyID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at FROM journey_stops WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var id, locID, stopType string
		var seq, dwell int
		var estimatedAt, completedAt *timeT
		if rows.Scan(&id, &locID, &stopType, &seq, &estimatedAt, &dwell, &completedAt) != nil {
			continue
		}
		st := map[string]interface{}{"stopId": id, "locationId": locID, "stopType": stopType, "sequence": seq, "dwellMinutes": dwell}
		if estimatedAt != nil {
			st["estimatedAt"] = estimatedAt.Format(rfc3339)
		}
		if completedAt != nil {
			st["completedAt"] = completedAt.Format(rfc3339)
		}
		out = append(out, st)
	}
	if out == nil {
		out = []map[string]interface{}{}
	}
	return out
}

