	if req.TargetJourneyID == "" || req.IdempotencyKey == "" || len(req.SourceJourneyIDs) == 0 {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "targetJourneyId, sourceJourneyIds, idempotencyKey required")
		return
	}
	var version int
	var targetSamples []string
	row := s.DB.QueryRow(r.Context(), `SELECT plan_version, sample_ids FROM journeys WHERE id=$1`, req.TargetJourneyID)
