		_, _ = s.DB.Exec(r.Context(), `UPDATE journeys SET status='merged', updated_at=now() WHERE id=$1`, jid)
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE journeys SET sample_ids=$1, plan_version=plan_version+1, updated_at=now() WHERE id=$2`, targetSamples, req.TargetJourneyID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sourceJourneyIds": req.SourceJourneyIDs})
	WriteData(w, http.StatusCreated, map[string]interface{}{"journeyId": req.TargetJourneyID, "sampleIds": targetSamples})
}

type rerouteJourneyReq struct {
	JourneyID           string `json:"journeyId"`
	ExpectedPlanVersion int    `json:"expectedPlanVersion"`
	Reason              string `json:"reason"`
	IdempotencyKey      string `json:"idempotencyKey"`
}

func (s *Server) HandleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req rerouteJourneyReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.JourneyID == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "journeyId, idempotencyKey required")
		return
	}
	var version int
	var sampleIDs []string
	row := s.DB.QueryRow(r.Context(), `SELECT plan_version, sample_ids FROM journeys WHERE id=$1`, req.JourneyID)
	if err := row.Scan(&version, &sampleIDs); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if version != req.ExpectedPlanVersion {
		WriteErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}

	replanStatus := "not_required"
	var replacementJourneyID *string
	if len(sampleIDs) > 0 {
		sampleID := sampleIDs[0]
		var labID, sampleTypeID string
		_ = s.DB.QueryRow(r.Context(), `SELECT target_laboratory_id, sample_type_id FROM samples sam JOIN requests req ON req.id=sam.request_id
			WHERE sam.id=$1`, sampleID).Scan(&labID, &sampleTypeID)

		var lastLoc *string
		_ = s.DB.QueryRow(r.Context(), `SELECT to_location_id FROM assignments WHERE journey_id=$1 AND status='completed' ORDER BY sequence DESC LIMIT 1`, req.JourneyID).Scan(&lastLoc)
		start := ""
		if lastLoc != nil {
			start = *lastLoc
		}
		if start != "" && labID != "" {
			newJourneyID, _, err := s.planJourneyFromPoint(r.Context(), sampleID, start, labID, sampleTypeID)
			if err == nil && newJourneyID != "" {
				replanStatus = "replaced"
				replacementJourneyID = &newJourneyID
				_, _ = s.DB.Exec(r.Context(), `UPDATE journeys SET status='superseded', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, req.JourneyID)
			} else {
				replanStatus = "expired"
				_, _ = s.DB.Exec(r.Context(), `UPDATE samples SET status='expired', updated_at=now() WHERE id=$1`, sampleID)
			}
		} else {
			replanStatus = "exception"
		}
	}
	s.Audit(r.Context(), u.UserID, u.ActiveRole, "reroute_journey", "journey", req.JourneyID, true, map[string]interface{}{"replanStatus": replanStatus})
	resp := map[string]interface{}{"journeyId": req.JourneyID, "replanStatus": replanStatus}
	if replacementJourneyID != nil {
		resp["replacementPlanId"] = *replacementJourneyID
		resp["replacementJourney"] = map[string]interface{}{"journeyId": *replacementJourneyID}
	}
	WriteData(w, http.StatusCreated, resp)
}

type editActivePlanReq struct {
	JourneyID           string                 `json:"journeyId"`
	ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
	ChangeType          string                 `json:"changeType"`
	Changes             map[string]interface{} `json:"changes"`
	IdempotencyKey      string                 `json:"idempotencyKey"`
}

func (s *Server) HandleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
	if u == nil {
		return
	}
	var req editActivePlanReq
	if !DecodeJSON(w, r, &req) {
		return
	}
	if req.JourneyID == "" || req.ChangeType == "" || req.IdempotencyKey == "" {
		WriteErr(w, http.StatusBadRequest, "idempotency_required", "journeyId, changeType, idempotencyKey required")
		return
	}
	var version int
	row := s.DB.QueryRow(r.Context(), `SELECT plan_version FROM journeys WHERE id=$1`, req.JourneyID)
	if err := row.Scan(&version); err != nil {
		WriteErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if version != req.ExpectedPlanVersion {
		WriteErr(w, http.StatusConflict, "stale_plan", "plan version mismatch")
		return
	}
	_, err := s.DB.Exec(r.Context(), `UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE id=$1`, req.JourneyID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
