    26  func generateToken() string {
    27          b := make([]byte, 24)
    28          _, _ = rand.Read(b)
    29          return hex.EncodeToString(b)
    30  }
    31
    32  func (s *Server) createSession(ctx context.Context, userID string, roles []string) (string, bool, error) {
    33          token := generateToken()
    34          roleSelectionRequired := true
    35          var activeRole *string
    36          if len(roles) == 1 {
    37                  roleSelectionRequired = false
    38                  activeRole = &roles[0]
    39          }
    40          _, err := s.DB.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role, role_selection_required, created_at, expires_at)
    41                  VALUES ($1,$2,$3,$4, now(), now() + interval '24 hours')`, token, userID, activeRole, roleSelectionRequired)
    42          if err != nil {
    43                  return "", false, err
    44          }
    45          return token, roleSelectionRequired, nil
    46  }
    47
    48  func (s *Server) resolveSession(ctx context.Context, token string) (*AuthUser, error) {
    49          var userID, username string
    50          var roles []string
    51          var activeRole *string
    52          var active bool
    53          row := s.DB.QueryRow(ctx, `SELECT u.id, u.username, u.roles, s.active_role, u.active
    54                  FROM sessions s JOIN users u ON u.id = s.user_id
    55                  WHERE s.token = $1 AND (s.expires_at IS NULL OR s.expires_at > now())`, token)
    56          if err := row.Scan(&userID, &username, &roles, &activeRole, &active); err != nil {
    57                  return nil, err
    58          }
    59          if !active {
    60                  return nil, pgx.ErrNoRows
    61          }
    62          au := &AuthUser{UserID: userID, Username: username, Roles: roles, Token: token}
    63          if activeRole != nil {
    64                  au.ActiveRole = *activeRole
    65          }
    66          return au, nil
    67  }
    68
    69  // AuthMiddleware extracts bearer [REDACTED], resolves session, and stores AuthUser in context.
    70  // Endpoints requiring auth call RequireAuth() to fetch it.
    71  func (s *Server) AuthMiddleware(next http.Handler) http.Handler {
    72          return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    73                  authz := r.Header.Get("Authorization")
    74                  if strings.HasPrefix(authz, "Bearer ") {
    75                          token := strings.TrimPrefix(authz, "Bearer ")
    76                          if au, err := s.resolveSession(r.Context(), token); err == nil {
    77                                  ctx := context.WithValue(r.Context(), ctxUserKey, au)
    78                                  r = r.WithContext(ctx)
    79                          }
    80                  }
    81                  next.ServeHTTP(w, r)
    82          })
    83  }
    84
    85  func UserFromContext(r *http.Request) *AuthUser {
    86          v := r.Context().Value(ctxUserKey)
    87          if v == nil {
    88                  return nil
    89          }
    90          return v.(*AuthUser)
    91  }
