    31  // Publish stores an event. audienceRole may be empty (broadcast to all roles).
    32  func (h *EventHub) Publish(ctx context.Context, evType, entityType, entityID string, payload map[string]interface{}, audienceRole string, audienceUserID *string) {
    33          b, _ := json.Marshal(payload)
    34          _, _ = h.db.Exec(ctx, `INSERT INTO realtime_events (type, entity_type, entity_id, audience_role, audience_user_id, payload) VALUES ($1,$2,$3,$4,$5,$6)`,
    35                  evType, entityType, entityID, nullableStr(audienceRole), audienceUserID, b)
