    44
    45  // Since returns events after the given cursor visible to the given role (or all if role=="").
    46  func (h *EventHub) Since(ctx context.Context, since int64, role string, userID string) ([]Event, int64, error) {
    47          rows, err := h.db.Query(ctx, `SELECT id, type, entity_type, entity_id, payload, created_at FROM realtime_events
    48                  WHERE id > $1 AND (audience_role IS NULL OR audience_role = $2) AND (audience_user_id IS NULL OR audience_user_id::text = $3)
    49                  ORDER BY id ASC LIMIT 500`, since, role, userID)
    50          if err != nil {
    51                  return nil, since, err
    52          }
    53          defer rows.Close()
    54          var events []Event
    55          cursor := since
    56          for rows.Next() {
    57                  var e Event
    58                  var payload []byte
    59                  if err := rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &e.CreatedAt); err != nil {
    60                          return nil, since, err
    61                  }
    62                  _ = json.Unmarshal(payload, &e.Payload)
    63                  events = append(events, e)
    64                  cursor = e.ID
    65          }
    66          return events, cursor, nil
