    24  // HaversineKm returns distance in kilometers between two coordinates.
    25  func HaversineKm(lat1, lon1, lat2, lon2 float64) float64 {
    26          const R = 6371.0
    27          dLat := (lat2 - lat1) * math.Pi / 180
    28          dLon := (lon2 - lon1) * math.Pi / 180
    29          a := math.Sin(dLat/2)*math.Sin(dLat/2) +
    30                  math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLon/2)*math.Sin(dLon/2)
    31          c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
    32          return R * c
    33  }
