    23          rows, err := s.DB.Query(ctx, `SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
    24                  is_collection_point, is_transfer_point, is_hub, is_laboratory FROM locations WHERE active = true`)
    25          if err != nil {
