    27          }
    28          defer rows.Close()
    29          var out []LocationRow
    30          for rows.Next() {
    31                  var l LocationRow
    32                  if err := rows.Scan(&l.ID, &l.Name, &l.Lat, &l.Lon, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
    33                          &l.IsCollectionPoint, &l.IsTransferPoint, &l.IsHub, &l.IsLaboratory); err != nil {
    34                          return nil, err
