    41  // nearestCollectionPoint returns the nearest active collection point within its coverage radius.
    42  func nearestCollectionPoint(locs []LocationRow, lat, lon float64) *LocationRow {
    43          var best *LocationRow
    44          bestDist := 1e18
    45          for i := range locs {
    46                  l := &locs[i]
    47                  if !l.IsCollectionPoint || !l.Active {
    48                          continue
    49                  }
    50                  d := util.HaversineKm(lat, lon, l.Lat, l.Lon)
    51                  if d <= l.CoverageKm && d < bestDist {
    52                          bestDist = d
    53                          best = l
    54                  }
    55          }
    56          return best
    57  }
