    85
    86  // shortestPath computes minimal travel-minutes path between from and to using
    87  // available connections (both directions traversable), optionally requiring
    88  // cooled connections. Returns ordered location IDs (including from & to) and
    89  // the connection IDs used, or nil if no route.
    90  func shortestPath(conns []ConnectionRow, from, to string, needCooled bool) ([]string, []string, int) {
    91          type edge struct {
    92                  to     string
    93                  connID string
    94                  weight int
    95                  cooled bool
    96          }
    97          adj := map[string][]edge{}
    98          for _, c := range conns {
    99                  if needCooled && !c.Cooled {
   100                          continue
   101                  }
   102                  adj[c.FromID] = append(adj[c.FromID], edge{c.ToID, c.ID, c.TravelMinutes, c.Cooled})
   103                  adj[c.ToID] = append(adj[c.ToID], edge{c.FromID, c.ID, c.TravelMinutes, c.Cooled})
   104          }
   105          if from == to {
   106                  return []string{from}, nil, 0
   107          }
   108          const inf = 1 << 30
   109          dist := map[string]int{from: 0}
   110          prevLoc := map[string]string{}
   111          prevConn := map[string]string{}
   112          visited := map[string]bool{}
   113          for {
   114                  // pick unvisited node with min dist
   115                  cur := ""
   116                  curDist := inf
   117                  for k, d := range dist {
   118                          if !visited[k] && d < curDist {
   119                                  cur = k
   120                                  curDist = d
   121                          }
   122                  }
   123                  if cur == "" {
   124                          break
   125                  }
   126                  if cur == to {
   127                          break
   128                  }
   129                  visited[cur] = true
   130                  for _, e := range adj[cur] {
   131                          nd := curDist + e.weight
   132                          if ed, ok := dist[e.to]; !ok || nd < ed {
   133                                  dist[e.to] = nd
   134                                  prevLoc[e.to] = cur
   135                                  prevConn[e.to] = e.connID
   136                          }
   137                  }
   138          }
   139          if _, ok := dist[to]; !ok {
   140                  return nil, nil, 0
   141          }
   142          // reconstruct
   143          var pathLoc []string
   144          var pathConn []string
   145          cur := to
   146          for cur != from {
   147                  pathLoc = append([]string{cur}, pathLoc...)
   148                  pathConn = append([]string{prevConn[cur]}, pathConn...)
   149                  cur = prevLoc[cur]
   150          }
   151          pathLoc = append([]string{from}, pathLoc...)
   152          return pathLoc, pathConn, dist[to]
   153  }
