   163  type CapacityRow struct {
   164          CapacityUnits       int
   165          ReservedUnits       int
   166          AvailableUnits      int
   167          CooledCapacityUnits int
   168          CooledReservedUnits int
   169          CooledAvailable     int
   170  }
   171
   172  func (s *Server) getOrCreateCapacity(ctx context.Context, resourceType, resourceID string) (CapacityRow, error) {
   173          var c CapacityRow
   174          row := s.DB.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   175                  FROM capacities WHERE resource_type=$1 AND resource_id=$2`, resourceType, resourceID)
   176          err := row.Scan(&c.CapacityUnits, &c.ReservedUnits, &c.CooledCapacityUnits, &c.CooledReservedUnits)
   177          if errors.Is(err, pgx.ErrNoRows) {
   178                  _, err2 := s.DB.Exec(ctx, `INSERT INTO capacities (resource_type, resource_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
   179                          VALUES ($1,$2,0,0,0,0) ON CONFLICT DO NOTHING`, resourceType, resourceID)
   180                  if err2 != nil {
   181                          return c, err2
   182                  }
   183                  return CapacityRow{}, nil
   184          }
   185          if err != nil {
   186                  return c, err
   187          }
   188          c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
   189          c.CooledAvailable = c.CooledCapacityUnits - c.CooledReservedUnits
   190          return c, nil
   191  }
   192
   193  // reserveCapacity attempts to reserve 1 unit (regular or cooled) atomically; returns ok.
   194  func (s *Server) reserveCapacity(ctx context.Context, resourceType, resourceID string, cooled bool, units int) (bool, error) {
   195          if units <= 0 {
   196                  units = 1
   197          }
   198          var sql string
   199          if cooled {
   200                  sql = `UPDATE capacities SET reserved_units = reserved_units,
   201                          cooled_reserved_units = cooled_reserved_units + $3
   202                          WHERE resource_type=$1 AND resource_id=$2 AND (cooled_capacity_units - cooled_reserved_units) >= $3`
   203          } else {
   204                  sql = `UPDATE capacities SET reserved_units = reserved_units + $3
   205                          WHERE resource_type=$1 AND resource_id=$2 AND (capacity_units - reserved_units) >= $3`
   206          }
   207          tag, err := s.DB.Exec(ctx, sql, resourceType, resourceID, units)
   208          if err != nil {
   209                  return false, err
   210          }
   211          return tag.RowsAffected() > 0, nil
   212  }
   213
   214  func (s *Server) releaseCapacity(ctx context.Context, resourceType, resourceID string, cooled bool, units int) error {
   215          if units <= 0 {
   216                  units = 1
   217          }
   218          var sql string
   219          if cooled {
   220                  sql = `UPDATE capacities SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - $3)
   221                          WHERE resource_type=$1 AND resource_id=$2`
   222          } else {
   223                  sql = `UPDATE capacities SET reserved_units = GREATEST(0, reserved_units - $3)
   224                          WHERE resource_type=$1 AND resource_id=$2`
   225          }
   226          _, err := s.DB.Exec(ctx, sql, resourceType, resourceID, units)
   227          return err
   228  }

