    12  // ServiceabilitySnapshot holds a complete, published snapshot of the network's
    13  // serviceability regions. Requests are always checked against the latest
    14  // COMPLETE snapshot, never a partially computed one.
    15  type ServiceabilitySnapshot struct {
    16          Version                    int                      `json:"version"`
    17          Status                     string                   `json:"status"`
    18          ComputedAt                 time.Time                `json:"computedAt"`
    19          NetworkRevision            int                      `json:"networkRevision"`
    20          Regions                    []map[string]interface{} `json:"regions"`
    21          ActiveCollectionPointCount int                      `json:"activeCollectionPointCount"`
    22  }
    23
    24  var snapMu sync.RWMutex
    25  var currentSnapshot *ServiceabilitySnapshot
    26
    27  func (s *Server) CurrentSnapshot() *ServiceabilitySnapshot {
    28          snapMu.RLock()
    29          defer snapMu.RUnlock()
    30          return currentSnapshot
    31  }
    32
    33  // recomputeServiceability builds a new snapshot from active collection points
    34  // and publishes it atomically once complete. Older snapshot keeps serving
    35  // concurrent readers until this finishes.
    36  func (s *Server) recomputeServiceability(ctx context.Context) {
    37          locs, err := s.loadActiveLocations(ctx)
    38          if err != nil {
    39                  return
    40          }
    41          var regions []map[string]interface{}
    42          count := 0
    43          for _, l := range locs {
    44                  if l.IsCollectionPoint && l.Active {
    45                          count++
    46                          regions = append(regions, map[string]interface{}{
    47                                  "locationId": l.ID, "name": l.Name, "latitude": l.Lat, "longitude": l.Lon, "coverageKm": l.CoverageKm,
    48                          })
    49                  }
    50          }
    51          var revision int
    52          _ = s.DB.QueryRow(ctx, `SELECT revision FROM network_revision WHERE id=1`).Scan(&revision)
    53
    54          var nextVersion int
    55          _ = s.DB.QueryRow(ctx, `SELECT COALESCE(MAX(version),0)+1 FROM serviceability_snapshots`).Scan(&nextVersion)
    56
    57          snap := &ServiceabilitySnapshot{
    58                  Version: nextVersion, Status: "complete", ComputedAt: util.NowUTC(),
    59                  NetworkRevision: revision, Regions: regions, ActiveCollectionPointCount: count,
    60          }
    61          regionsJSON, _ := json.Marshal(regions)
    62          _, _ = s.DB.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
    63                  VALUES ($1,$2,$3,$4,$5,$6)`, snap.Version, snap.Status, snap.ComputedAt, snap.NetworkRevision, regionsJSON, snap.ActiveCollectionPointCount)
    64
    65          snapMu.Lock()
    66          currentSnapshot = snap
    67          snapMu.Unlock()
    68  }
    69
    70  func (s *Server) ensureSnapshotLoaded(ctx context.Context) {
    71          if s.CurrentSnapshot() != nil {
    72                  return
    73          }
    74          var version, revision, count int
    75          var computedAt time.Time
    76          var regionsRaw []byte
    77          err := s.DB.QueryRow(ctx, `SELECT version, computed_at, network_revision, regions, active_collection_point_count
    78                  FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).Scan(&version, &computedAt, &revision, &regionsRaw, &count)
    79          if err != nil {
    80                  s.recomputeServiceability(ctx)
    81                  return
    82          }
    83          var regions []map[string]interface{}
    84          _ = json.Unmarshal(regionsRaw, &regions)
    85          snapMu.Lock()
    86          currentSnapshot = &ServiceabilitySnapshot{Version: version, Status: "complete", ComputedAt: computedAt, NetworkRevision: revision, Regions: regions, ActiveCollectionPointCount: count}
    87          snapMu.Unlock()
    88  }
