    11  type checkServiceabilityReq struct {
    12          Origin              coordinateReq `json:"origin"`
    13          OriginType          string        `json:"originType"`
    14          OriginNodeID        *string       `json:"originNodeId"`
    15          SampleTypeID        string        `json:"sampleTypeId"`
    16          RequestedAt         string        `json:"requestedAt"`
    17          DeliveryDeadline    string        `json:"deliveryDeadline"`
    18          EarliestCollectionAt string       `json:"earliestCollectionAt"`
    19          LatestCollectionAt  string        `json:"latestCollectionAt"`
    20  }
    21
    22  type ServiceabilityResult struct {
    23          Serviceable          bool
    24          Reason               string
    25          TargetLaboratoryID   string
    26          EstimatedArrivalAt   *time.Time
    27  }
    28
    29  // evaluateServiceability is a pure function of network structure (not worker
    30  // availability) used both by the dry-run check and by request creation.
    31  func (s *Server) evaluateServiceability(ctx context.Context, origin coordinateReq, originType string, originNodeID *string,
    32          sampleTypeID string, deliveryDeadline time.Time) ServiceabilityResult {
    33
    34          locs, err := s.loadActiveLocations(ctx)
    35          if err != nil {
    36                  return ServiceabilityResult{Serviceable: false, Reason: "no_route"}
    37          }
    38          conns, err := s.loadActiveConnections(ctx)
    39          if err != nil {
    40                  return ServiceabilityResult{Serviceable: false, Reason: "no_route"}
    41          }
    42
    43          var startLocID string
    44          var startLat, startLon float64
    45          if originType == "node" && originNodeID != nil {
    46                  found := false
    47                  for _, l := range locs {
    48                          if l.ID == *originNodeID {
    49                                  startLocID = l.ID
    50                                  startLat, startLon = l.Lat, l.Lon
    51                                  found = true
    52                                  break
    53                          }
    54                  }
    55                  if !found {
    56                          return ServiceabilityResult{Serviceable: false, Reason: "outside_service_coverage"}
    57                  }
    58          } else {
    59                  nearest := nearestCollectionPoint(locs, origin.Latitude, origin.Longitude)
    60                  if nearest == nil {
    61                          return ServiceabilityResult{Serviceable: false, Reason: "outside_service_coverage"}
    62                  }
    63                  startLocID = nearest.ID
    64                  startLat, startLon = nearest.Lat, nearest.Lon
    65          }
    66          _ = startLat
    67          _ = startLon
    68
    69          // sample type handling rules
    70          var requiresCooled bool
    71          err = s.DB.QueryRow(ctx, `SELECT requires_cooled_route FROM sample_types WHERE id=$1`, sampleTypeID).Scan(&requiresCooled)
    72          if err != nil {
    73                  return ServiceabilityResult{Serviceable: false, Reason: "handling_rules_unsatisfiable"}
    74          }
    75
    76          // find any active laboratory accepting this sample type reachable from startLocID
    77          rows, err := s.DB.Query(ctx, `SELECT laboratory_id FROM laboratory_acceptance WHERE sample_type_id=$1 AND accepts=true`, sampleTypeID)
    78          if err != nil {
    79                  return ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory"}
    80          }
    81          var labIDs []string
    82          for rows.Next() {
    83                  var id string
    84                  if err := rows.Scan(&id); err == nil {
    85                          labIDs = append(labIDs, id)
    86                  }
    87          }
    88          rows.Close()
    89          if len(labIDs) == 0 {
    90                  return ServiceabilityResult{Serviceable: false, Reason: "no_accepting_laboratory"}
    91          }
    92
    93          activeLabSet := map[string]bool{}
    94          for _, l := range locs {
    95                  if l.IsLaboratory && l.Active {
    96                          activeLabSet[l.ID] = true
    97                  }
    98          }
    99
   100          bestArrival := time.Time{}
   101          bestLab := ""
   102          found := false
   103          for _, labID := range labIDs {
   104                  if !activeLabSet[labID] {
   105                          continue
   106                  }
   107                  _, _, minutes := shortestPath(conns, startLocID, labID, requiresCooled)
   108                  if minutes == 0 && startLocID != labID {
   109                          continue
   110                  }
   111                  arrival := util.NowUTC().Add(time.Duration(minutes) * time.Minute)
   112                  if !found || arrival.Before(bestArrival) {
   113                          bestArrival = arrival
   114                          bestLab = labID
   115                          found = true
   116                  }
   117          }
   118          if !found {
   119                  return ServiceabilityResult{Serviceable: false, Reason: "no_route"}
   120          }
   121          if bestArrival.After(deliveryDeadline) {
   122                  return ServiceabilityResult{Serviceable: false, Reason: "deadline_unreachable", TargetLaboratoryID: bestLab, EstimatedArrivalAt: &bestArrival}
   123          }
   124
   125          // capacity check: at least one unit of relevant capacity available at destination lab
   126          cap, err := s.getOrCreateCapacity(ctx, "location", bestLab)
   127          if err == nil {
   128                  if requiresCooled {
   129                          if cap.CooledCapacityUnits > 0 && cap.CooledAvailable <= 0 {
   130                                  return ServiceabilityResult{Serviceable: false, Reason: "insufficient_capacity", TargetLaboratoryID: bestLab}
   131                          }
   132                  } else {
   133                          if cap.CapacityUnits > 0 && cap.AvailableUnits <= 0 {
   134                                  return ServiceabilityResult{Serviceable: false, Reason: "insufficient_capacity", TargetLaboratoryID: bestLab}
   135                          }
   136                  }
   137          }
   138
   139          return ServiceabilityResult{Serviceable: true, Reason: "serviceable", TargetLaboratoryID: bestLab, EstimatedArrivalAt: &bestArrival}
   140  }
