   142  func (s *Server) HandleCheckServiceability(w http.ResponseWriter, r *http.Request) {
   143          u := RequireRole(w, r, RoleRequester, RoleDispatcher, RoleAdministrator)
   144          if u == nil {
   145                  return
   146          }
   147          var req checkServiceabilityReq
   148          if !DecodeJSON(w, r, &req) {
   149                  return
   150          }
   151          if req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
   152                  WriteErr(w, http.StatusBadRequest, "invalid_json", "sampleTypeId, requestedAt, deliveryDeadline required")
   153                  return
   154          }
   155          deadline, err := util.ParseTime(req.DeliveryDeadline)
   156          if err != nil {
   157                  WriteErr(w, http.StatusBadRequest, "invalid_deadline", "invalid deliveryDeadline")
   158                  return
   159          }
   160          if req.EarliestCollectionAt != "" && req.LatestCollectionAt != "" {
   161                  early, e1 := util.ParseTime(req.EarliestCollectionAt)
   162                  late, e2 := util.ParseTime(req.LatestCollectionAt)
   163                  if e1 != nil || e2 != nil || late.Before(early) {
   164                          WriteErr(w, http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
   165                          return
   166                  }
   167          }
   168          originType := req.OriginType
   169          if originType == "" {
   170                  originType = "home"
   171          }
   172          if originType != "home" && originType != "clinic" && originType != "node" {
   173                  WriteErr(w, http.StatusBadRequest, "invalid_origin_type", "invalid originType")
   174                  return
   175          }
   176
   177          s.ensureSnapshotLoaded(r.Context())
   178          snap := s.CurrentSnapshot()
   179          version := 1
   180          if snap != nil {
   181                  version = snap.Version
   182          }
   183
   184          result := s.evaluateServiceability(r.Context(), req.Origin, originType, req.OriginNodeID, req.SampleTypeID, deadline)
   185
   186          s.Audit(r.Context(), u.UserID, u.ActiveRole, "check_serviceability", "serviceability", req.SampleTypeID, true, map[string]interface{}{
   187                  "serviceable": result.Serviceable, "reason": result.Reason,
   188          })
   189
   190          resp := map[string]interface{}{
   191                  "serviceable":          result.Serviceable,
   192                  "reason":               result.Reason,
   193                  "serviceabilityVersion": version,
   194          }
   195          if result.TargetLaboratoryID != "" {
   196                  resp["targetLaboratoryId"] = result.TargetLaboratoryID
   197          }
   198          if result.EstimatedArrivalAt != nil {
   199                  resp["estimatedArrivalAt"] = result.EstimatedArrivalAt.Format(time.RFC3339)
   200          }
   201          WriteData(w, http.StatusOK, resp)
   202  }
