    29                  s.Audit(r.Context(), req.Username, "", "sign_in", "user", req.Username, false, map[string]interface{}{"reason": "not_found"})
    30                  WriteErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid username or password")
    31                  return
