    33          if !active || bcrypt.CompareHashAndPassword([]byte(hash), []byte(req.Password)) != nil {
    34                  s.Audit(r.Context(), userID, "", "sign_in", "user", userID, false, map[string]interface{}{"reason": "bad_credentials"})
    35                  WriteErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid username or password")
