    38          token, roleSelectionRequired, err := s.createSession(r.Context(), userID, roles)
    39          if err != nil {
    40                  WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
    41                  return
    42          }
    43          activeRole := ""
    44          if !roleSelectionRequired && len(roles) > 0 {
    45                  activeRole = roles[0]
    46          }
    47          s.Audit(r.Context(), userID, activeRole, "sign_in", "user", userID, true, nil)
    48          WriteData(w, http.StatusOK, map[string]interface{}{
    49                  "sessionToken": token,
    50                  "userId":       userID,
    51                  "roles":        roles,
    52                  "activeRole":   activeRole,
