    83  func (s *Server) HandleUpdateSampleType(w http.ResponseWriter, r *http.Request) {
    84          u := RequireRole(w, r, RoleAdministrator)
    85          if u == nil {
    86                  return
    87          }
    88          var req updateSampleTypeReq
    89          if !DecodeJSON(w, r, &req) {
    90                  return
    91          }
    92          if req.SampleTypeID == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
    93                  WriteErr(w, http.StatusBadRequest, "invalid_json", "sampleTypeId, containerType, temperatureMinC, temperatureMaxC required")
    94                  return
    95          }
    96          var name string
    97          var qualReq, cooled, batching bool
    98          row := s.DB.QueryRow(r.Context(), `SELECT name, qualified_collector_required, requires_cooled_route, batching_allowed FROM sample_types WHERE id=$1`, req.SampleTypeID)
    99          if err := row.Scan(&name, &qualReq, &cooled, &batching); err != nil {
   100                  WriteErr(w, http.StatusNotFound, "not_found", "sample type not found")
   101                  return
   102          }
   103          if req.QualifiedCollectorRequired != nil {
   104                  qualReq = *req.QualifiedCollectorRequired
   105          }
   106          if req.RequiresCooledRoute != nil {
   107                  cooled = *req.RequiresCooledRoute
   108          }
   109          if req.BatchingAllowed != nil {
   110                  batching = *req.BatchingAllowed
   111          }
   112          incompat := req.IncompatibleSampleTypes
   113          if incompat == nil {
   114                  incompat = []string{}
   115          }
   116          _, err := s.DB.Exec(r.Context(), `UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3,
   117                  temperature_min_c=$4, temperature_max_c=$5, incompatible_sample_types=$6, requires_cooled_route=$7, batching_allowed=$8 WHERE id=$9`,
   118                  qualReq, req.RequiredQualification, req.ContainerType, *req.TemperatureMinC, *req.TemperatureMaxC, incompat, cooled, batching, req.SampleTypeID)
   119          if err != nil {
   120                  WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
   121                  return
   122          }
   123          s.Audit(r.Context(), u.UserID, u.ActiveRole, "update_sample_type", "sample_type", req.SampleTypeID, true, nil)
   124          WriteData(w, http.StatusCreated, sampleTypeToMap(req.SampleTypeID, name, qualReq, req.RequiredQualification, req.ContainerType, *req.TemperatureMinC, *req.TemperatureMaxC, incompat, cooled, batching))
   125  }
