   163  }
   164
   165  func (s *Server) HandleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
   166          u := RequireRole(w, r, RoleAdministrator, RoleNodeHandler, RoleLaboratoryTeam)
   167          if u == nil {
   168                  return
   169          }
   170          var req configureCapacityReq
   171          if !DecodeJSON(w, r, &req) || req.ResourceID == "" || req.CapacityUnits == nil {
   172                  WriteErr(w, http.StatusBadRequest, "invalid_json", "resourceId, capacityUnits required")
   173                  return
   174          }
   175          if u.ActiveRole != RoleAdministrator {
   176                  var assigned *string
   177                  _ = s.DB.QueryRow(r.Context(), `SELECT assigned_location_id FROM users WHERE id=$1`, u.UserID).Scan(&assigned)
   178                  if assigned == nil || *assigned != req.ResourceID {
   179                          WriteErr(w, http.StatusForbidden, "forbidden", "not assigned to this resource")
   180                          return
   181                  }
   182          }
   183          cooled := 0
   184          if req.CooledCapacityUnits != nil {
   185                  cooled = *req.CooledCapacityUnits
   186          }
   187          // resource type: location. either connection or location; look up in both.
   188          resType := "location"
   189          var exists bool
   190          _ = s.DB.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, req.ResourceID).Scan(&exists)
   191          if !exists {
   192                  _ = s.DB.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM connections WHERE id=$1)`, req.ResourceID).Scan(&exists)
   193                  if exists {
   194                          resType = "connection"
   195                  }
   196          }
   197          if !exists {
   198                  WriteErr(w, http.StatusNotFound, "not_found", "resource not found")
   199                  return
   200          }
   201          _, err := s.DB.Exec(r.Context(), `INSERT INTO capacities (resource_type, resource_id, capacity_units, cooled_capacity_units)
   202                  VALUES ($1,$2,$3,$4)
   203                  ON CONFLICT (resource_type, resource_id) DO UPDATE SET capacity_units=$3, cooled_capacity_units=$4`,
   204                  resType, req.ResourceID, *req.CapacityUnits, cooled)
   205          if err != nil {
   206                  WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
   207                  return
   208          }
   209          s.bumpNetworkRevision(r.Context())
   210          s.Audit(r.Context(), u.UserID, u.ActiveRole, "configure_capacity", resType, req.ResourceID, true, map[string]interface{}{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
   211          WriteData(w, http.StatusOK, map[string]interface{}{"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
   212  }
