package server

import (
	"encoding/base64"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin:  func(r *http.Request) bool { return true },
	Subprotocols: []string{"lab-logistics-v1"},
}

func eventsToJSON(events []Event) []map[string]interface{} {
	out := make([]map[string]interface{}, 0, len(events))
	for _, e := range events {
		out = append(out, map[string]interface{}{
			"id": e.ID, "type": e.Type, "entityType": e.EntityType, "entityId": e.EntityID,
			"payload": e.Payload, "createdAt": e.CreatedAt.Format(time.RFC3339),
		})
	}
	return out
}

// authFromWSProtocol extracts the bearer [REDACTED] from the base64url-encoded
// "bearer.<token>" WebSocket subprotocol value.
func authFromWSProtocol(r *http.Request) string {
	proto := r.Header.Get("Sec-WebSocket-Protocol")
	for _, p := range strings.Split(proto, ",") {
		p = strings.TrimSpace(p)
		decoded, err := base64.RawURLEncoding.DecodeString(p)
		if err != nil {
			decoded, err = base64.URLEncoding.DecodeString(p)
			if err != nil {
				continue
			}
		}
		s := string(decoded)
		if strings.HasPrefix(s, "bearer.") {
			return strings.TrimPrefix(s, "bearer.")
		}
	}
	return ""
}

func (s *Server) HandleEvents(w http.ResponseWriter, r *http.Request) {
	// WebSocket upgrade path
	if strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") ||
		strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		token := authFromWSProtocol(r)
		au, err := s.resolveSession(r.Context(), token)
		if err != nil {
			WriteErr(w, http.StatusUnauthorized, "unauthorized", "authentication required")
			return
		}
		conn, err := upgrader.Upgrade(w, r, nil)
		if err != nil {
			return
		}
		defer conn.Close()
		since := int64(0)
		if v := r.URL.Query().Get("since"); v != "" {
			since, _ = strconv.ParseInt(v, 10, 64)
		}
		for {
			events, cursor, err := s.Events.Since(r.Context(), since, au.ActiveRole, au.UserID)
			if err == nil && len(events) > 0 {
				since = cursor
				_ = conn.WriteJSON(map[string]interface{}{"data": map[string]interface{}{"events": eventsToJSON(events), "cursor": cursor}})
			}
			time.Sleep(1 * time.Second)
			if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}

	// Plain HTTP polling fallback
	u := RequireAuth(w, r)
	if u == nil {
		return
	}
	since := int64(0)
	if v := r.URL.Query().Get("since"); v != "" {
		since, _ = strconv.ParseInt(v, 10, 64)
	}
	events, cursor, err := s.Events.Since(r.Context(), since, u.ActiveRole, u.UserID)
	if err != nil {
		WriteErr(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	WriteData(w, http.StatusOK, map[string]interface{}{"events": eventsToJSON(events), "cursor": cursor})
}

func (s *Server) HandleReady(w http.ResponseWriter, r *http.Request) {
	if err := s.Ping(r.Context()); err != nil {
		WriteJSONStatus(w, http.StatusServiceUnavailable, map[string]interface{}{"status": "not_ready"})
		return
	}
	WriteJSONStatus(w, http.StatusOK, map[string]interface{}{"status": "ready"})
}

