import { createContext, useCallback, useContext, useEffect, useState } from "react";
import type { ReactNode } from "react";
import { api, setToken } from "./api";

interface AuthUser {
  userId: string;
  username: string;
  roles: string[];
  activeRole: string;
}

interface LoginResponse {
  sessionToken: string;
  userId: string;
  roles: string[];
  activeRole: string;
}

interface AuthContextValue {
  user: AuthUser | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
  selectRole: (role: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const stored = localStorage.getItem("authUser");
    if (stored) {
      try {
        setUser(JSON.parse(stored));
      } catch {
        /* ignore malformed cache */
      }
    }
    setLoading(false);
  }, []);

  const persist = useCallback((u: AuthUser | null) => {
    setUser(u);
    if (u) localStorage.setItem("authUser", JSON.stringify(u));
    else localStorage.removeItem("authUser");
  }, []);

  const login = useCallback(
    async (username: string, password: string) => {
      const data = await api.post<LoginResponse>("/authenticate-user", {
        username,
        password,
      });
      setToken(data.sessionToken);
      persist({
        userId: data.userId,
        username,
        roles: data.roles,
        activeRole: data.activeRole,
      });
    },
    [persist],
  );

  const logout = useCallback(() => {
    setToken(null);
    persist(null);
  }, [persist]);

  const selectRole = useCallback(
    async (role: string) => {
      const data = await api.post<{ activeRole: string; roles: string[] }>(
        "/select-active-role",
        { role },
      );
      if (user) {
        persist({ ...user, activeRole: data.activeRole, roles: data.roles });
      }
    },
    [user, persist],
  );

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, selectRole }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
}

export const ROLE_LABELS: Record<string, string> = {
  administrator: "Administrator",
  dispatcher: "Dispatcher",
  requester: "Requester",
  collection_professional: "Certified Collection Professional",
  relay_courier: "Relay Courier",
  node_handler: "Node Handler",
  laboratory_intake_operator: "Laboratory Intake Operator",
};

