package server

import (
        "net/http"
        "time"
)

func (s *Server) HandleReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
        u := RequireAuth(w, r)
        if u == nil {
                return
        }
        var roleSelectionRequired bool
        _ = s.DB.QueryRow(r.Context(), `SELECT role_selection_required FROM sessions WHERE token=$1`, u.Token).Scan(&roleSelectionRequired)
        var fullName *string
        _ = s.DB.QueryRow(r.Context(), `SELECT full_name FROM users WHERE id=$1`, u.UserID).Scan(&fullName)

        userMap := map[string]interface{}{
                "userId": u.UserID, "username": u.Username, "roles": u.Roles, "activeRole": u.ActiveRole,
                "roleSelectionRequired": roleSelectionRequired,
        }
        if fullName != nil {
                userMap["fullName"] = *fullName
        }

        resp := map[string]interface{}{"user": userMap, "serverTime": time.Now().UTC().Format(time.RFC3339)}

        if u.ActiveRole == RoleRequester {
                var samples []map[string]interface{}
                rows, err := s.DB.Query(r.Context(), `SELECT sam.id, sam.status FROM samples sam JOIN requests req ON req.id=sam.request_id
                        WHERE req.requester_id=$1 ORDER BY req.requested_at DESC LIMIT 50`, u.UserID)
                if err == nil {
                        defer rows.Close()
                        for rows.Next() {
                                var id, status string
                                if rows.Scan(&id, &status) == nil {
                                        samples = append(samples, map[string]interface{}{"sampleId": id, "status": status})
                                }
                        }
                }
                if samples == nil {
                        samples = []map[string]interface{}{}
                }
                resp["requesterSamples"] = samples
        }

        if u.ActiveRole == RoleDispatcher || u.ActiveRole == RoleAdministrator {
                resp["operations"] = map[string]interface{}{"available": true}
        }

        WriteData(w, http.StatusOK, resp)
}

package server

import (
        "context"
        "net/http"
        "time"
)

func (s *Server) sampleTimeline(ctx context.Context, sampleID string) []map[string]interface{} {
        rows, err := s.DB.Query(ctx, `SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
                FROM audit_log WHERE entity_id=$1 ORDER BY occurred_at ASC`, sampleID)
        if err != nil {
                return nil
        }
        defer rows.Close()
        var out []map[string]interface{}
        for rows.Next() {
                var id int64
                var action, actorID, entityType, entityID string
                var role *string
                var success bool
                var occurredAt time.Time
                var details []byte
                if err := rows.Scan(&id, &action, &actorID, &role, &entityType, &entityID, &success, &occurredAt, &details); err != nil {
                        continue
                }
                roleStr := ""
                if role != nil {
                        roleStr = *role
                }
                out = append(out, map[string]interface{}{
                        "eventId": id, "action": action, "actorId": actorID, "role": roleStr,
                        "entityType": entityType, "entityId": entityID, "success": success,
                        "occurredAt": occurredAt.Format(time.RFC3339), "details": rawJSONOrEmpty(details),
                })
        }
        return out
}

func (s *Server) HandleReadSampleState(w http.ResponseWriter, r *http.Request, sampleID string) {
        u := RequireAuth(w, r)
        if u == nil {
                return
        }
        sample, err := s.loadSample(r.Context(), sampleID)
        if err != nil {
                WriteErr(w, http.StatusNotFound, "not_found", "sample not found")
                return
        }
        if u.ActiveRole == RoleRequester && sample["requesterId"] != u.UserID {
                WriteErr(w, http.StatusForbidden, "forbidden", "not your sample")
                return
        }
        sample["timeline"] = s.sampleTimeline(r.Context(), sampleID)
        WriteData(w, http.StatusOK, sample)
}

func (s *Server) loadSample(ctx context.Context, sampleID string) (map[string]interface{}, error) {
        var requesterID, originType, sampleTypeID, containerType, status, serviceability string
        var deliveryDeadline, requestedAt time.Time
        var tmin, tmax, olat, olon float64
        var incompat []string
        var activeAssignmentIDs []string
        var activeJourneyID, targetLab, currentHolder *string
        var latLat, latLon *float64
        var locRecordedAt *time.Time
        var sealed bool
        row := s.DB.QueryRow(ctx, `SELECT req.requester_id, req.origin_type, req.origin_lat, req.origin_lon, req.requested_at, req.delivery_deadline,
                req.sample_type_id, req.container_type, req.temperature_min_c, req.temperature_max_c, req.incompatible_sample_types,
                sam.status, sam.serviceability, sam.active_journey_id, sam.target_laboratory_id, sam.current_holder_id, sam.sealed,
                sam.latest_lat, sam.latest_lon, sam.location_recorded_at
                FROM samples sam JOIN requests req ON req.id = sam.request_id WHERE sam.id=$1`, sampleID)
        if err := row.Scan(&requesterID, &originType, &olat, &olon, &requestedAt, &deliveryDeadline, &sampleTypeID, &containerType,
                &tmin, &tmax, &incompat, &status, &serviceability, &activeJourneyID, &targetLab, &currentHolder, &sealed, &latLat, &latLon, &locRecordedAt); err != nil {
                return nil, err
        }

        rows, err := s.DB.Query(ctx, `SELECT id FROM assignments WHERE sample_id=$1 AND status NOT IN ('completed','cancelled')`, sampleID)
        if err == nil {
                defer rows.Close()
                for rows.Next() {
                        var id string
                        if rows.Scan(&id) == nil {
                                activeAssignmentIDs = append(activeAssignmentIDs, id)
                        }
                }
        }
        if activeAssignmentIDs == nil {
                activeAssignmentIDs = []string{}
        }
        if incompat == nil {
                incompat = []string{}
        }

        stale := false
        var locRecStr *string
        if locRecordedAt != nil {
                if time.Since(*locRecordedAt) > 30*time.Minute {
                        stale = true
                }
                s2 := locRecordedAt.Format(time.RFC3339)
                locRecStr = &s2
        } else {
                stale = true
        }

        var requestID string
        _ = s.DB.QueryRow(ctx, `SELECT request_id FROM samples WHERE id=$1`, sampleID).Scan(&requestID)

        m := map[string]interface{}{
                "sampleId": sampleID, "requestId": requestID, "requesterId": requesterID,
                "origin": map[string]interface{}{"latitude": olat, "longitude": olon},
                "originType": originType, "requestedAt": requestedAt.Format(time.RFC3339), "deliveryDeadline": deliveryDeadline.Format(time.RFC3339),
                "sampleTypeId": sampleTypeID, "containerType": containerType, "temperatureMinC": tmin, "temperatureMaxC": tmax,
                "incompatibleSampleTypes": incompat, "serviceability": serviceability, "activeAssignmentIds": activeAssignmentIDs,
                "state": map[string]interface{}{"status": status}, "locationStale": stale,
        }
        if activeJourneyID != nil {
                m["activeJourneyId"] = *activeJourneyID
        }
        if targetLab != nil {
                m["targetLaboratoryId"] = *targetLab
        }
        if currentHolder != nil {
                m["currentHolderId"] = *currentHolder
        }
        if latLat != nil && latLon != nil {
                m["latestLocation"] = map[string]interface{}{"latitude": *latLat, "longitude": *latLon}
        }
        if locRecStr != nil {
                m["locationRecordedAt"] = *locRecStr
        }
        return m, nil
}

