import { Navigate, Route, Routes } from "react-router-dom";
import { useAuth } from "./AuthContext";
import Layout from "./Layout";
import LoginPage from "./pages/LoginPage";
import DashboardPage from "./pages/DashboardPage";
import RequestPage from "./pages/RequestPage";
import SampleDetailPage from "./pages/SampleDetailPage";
import MapPage from "./pages/MapPage";
import MonitorPage from "./pages/MonitorPage";
import AuditPage from "./pages/AuditPage";
import AdminUsersPage from "./pages/AdminUsersPage";
import AdminNetworkPage from "./pages/AdminNetworkPage";
import AdminSampleTypesPage from "./pages/AdminSampleTypesPage";
import CapacityPage from "./pages/CapacityPage";

function RequireAuth({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) return <div className="page-loading">Loading…</div>;
  if (!user) return <Navigate to="/login" replace />;
  return <>{children}</>;
}

export default function App() {
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route
        path="/*"
        element={
          <RequireAuth>
            <Layout />
          </RequireAuth>
        }
      >
        <Route index element={<DashboardPage />} />
        <Route path="request" element={<RequestPage />} />
        <Route path="samples/:sampleId" element={<SampleDetailPage />} />
        <Route path="map" element={<MapPage />} />
        <Route path="monitor" element={<MonitorPage />} />
        <Route path="audit" element={<AuditPage />} />
        <Route path="capacity" element={<CapacityPage />} />
        <Route path="admin/users" element={<AdminUsersPage />} />
        <Route path="admin/network" element={<AdminNetworkPage />} />
        <Route path="admin/sample-types" element={<AdminSampleTypesPage />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
  );
}

