import { NavLink, Outlet, useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import { useAuth, ROLE_LABELS } from "./AuthContext";

export default function Layout() {
  const { user, logout, selectRole } = useAuth();
  const navigate = useNavigate();
  const [switching, setSwitching] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!user) return;
  }, [user]);

  if (!user) return null;

  const isDispatcherLike =
    user.activeRole === "dispatcher" || user.activeRole === "administrator";
  const isAdmin = user.activeRole === "administrator";
  const isWorkerRole = [
    "collection_professional",
    "delivery_partner",
    "node_handler",
    "laboratory_team",
  ].includes(user.activeRole);

  async function onRoleChange(e: React.ChangeEvent<HTMLSelectElement>) {
    const role = e.target.value;
    setSwitching(true);
    setError(null);
    try {
      await selectRole(role);
      navigate("/");
    } catch (err) {
      const e2 = err as { error?: string };
      setError(e2.error || "Failed to switch role");
    } finally {
      setSwitching(false);
    }
  }

  return (
    <div className="app-shell">
      <header className="app-header">
        <div className="brand">Lab Sample Logistics</div>
        <nav className="main-nav" aria-label="Main navigation">
          <NavLink to="/" end>
            Dashboard
          </NavLink>
          {user.activeRole === "requester" && (
            <NavLink to="/request">New Request</NavLink>
          )}
          <NavLink to="/map">Map</NavLink>
          {isDispatcherLike && <NavLink to="/monitor">Monitor</NavLink>}
          {isDispatcherLike && <NavLink to="/audit">Audit Log</NavLink>}
          {(isWorkerRole || isDispatcherLike) && (
            <NavLink to="/capacity">Capacity</NavLink>
          )}
          {isAdmin && <NavLink to="/admin/users">Users</NavLink>}
          {isAdmin && <NavLink to="/admin/network">Network</NavLink>}
          {isAdmin && (
            <NavLink to="/admin/sample-types">Sample Types</NavLink>
          )}
        </nav>
        <div className="header-account">
          <label htmlFor="role-select" className="role-select-label">
            Acting as
          </label>
          <select
            id="role-select"
            aria-label="Acting as role"
            value={user.activeRole}
            disabled={switching}
            onChange={onRoleChange}
          >
            {user.roles.map((role) => (
              <option key={role} value={role}>
                {ROLE_LABELS[role] || role}
              </option>
            ))}
          </select>
          <span className="username" aria-label="Signed in as">
            {user.username}
          </span>
          <button
            type="button"
            onClick={() => {
              logout();
              navigate("/login");
            }}
          >
            Sign out
          </button>
        </div>
      </header>
      {error && (
        <div role="alert" className="banner banner-error">
          {error}
        </div>
      )}
      <main className="app-main">
        <Outlet />
      </main>
    </div>
  );
}

