import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { api, newIdempotencyKey } from "../api";
import type { ApiError } from "../api";

interface ServiceabilityResult {
  serviceable: boolean;
  reason: string;
  targetLaboratoryId?: string;
  estimatedArrivalAt?: string;
  serviceabilityVersion: number;
}

interface CreateRequestResult {
  requestId: string;
  sampleId: string;
  serviceability: string;
  serviceabilityReason?: string;
  activeAssignmentIds: string[];
  earliestCollectionAt: string;
  latestCollectionAt: string;
  journeyId?: string;
  targetLaboratoryId?: string;
}

const ORIGIN_TYPES = ["home", "clinic", "node"];

export default function RequestPage() {
  const navigate = useNavigate();
  const [originType, setOriginType] = useState("home");
  const [latitude, setLatitude] = useState("12.9716");
  const [longitude, setLongitude] = useState("77.5946");
  const [originNodeId, setOriginNodeId] = useState("");
  const [sampleTypeId, setSampleTypeId] = useState("");
  const [containerType, setContainerType] = useState("standard-vial");
  const [temperatureMinC, setTemperatureMinC] = useState("2");
  const [temperatureMaxC, setTemperatureMaxC] = useState("8");
  const [earliestCollectionAt, setEarliestCollectionAt] = useState("");
  const [latestCollectionAt, setLatestCollectionAt] = useState("");
  const [deliveryDeadline, setDeliveryDeadline] = useState("");

  const [checking, setChecking] = useState(false);
  const [checkResult, setCheckResult] = useState<ServiceabilityResult | null>(
    null,
  );
  const [checkError, setCheckError] = useState<string | null>(null);

  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitResult, setSubmitResult] = useState<CreateRequestResult | null>(
    null,
  );

  function buildOrigin() {
    return { latitude: parseFloat(latitude), longitude: parseFloat(longitude) };
  }

  function basePayload() {
    const now = new Date().toISOString();
    return {
      origin: buildOrigin(),
      originType,
      originNodeId: originType === "node" ? originNodeId : undefined,
      sampleTypeId,
      requestedAt: now,
      deliveryDeadline: deliveryDeadline
        ? new Date(deliveryDeadline).toISOString()
        : undefined,
      earliestCollectionAt: earliestCollectionAt
        ? new Date(earliestCollectionAt).toISOString()
        : undefined,
      latestCollectionAt: latestCollectionAt
        ? new Date(latestCollectionAt).toISOString()
        : undefined,
    };
  }

  async function onCheck(e: React.FormEvent) {
    e.preventDefault();
    setChecking(true);
    setCheckError(null);
    setCheckResult(null);
    try {
      const data = await api.post<ServiceabilityResult>(
        "/check-serviceability",
        basePayload(),
      );
      setCheckResult(data);
    } catch (err) {
      const e2 = err as ApiError;
      setCheckError(e2.error || "Serviceability check failed");
    } finally {
      setChecking(false);
    }
  }

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    setSubmitError(null);
    setSubmitResult(null);
    try {
      const data = await api.post<CreateRequestResult>(
        "/create-collection-request",
        {
          ...basePayload(),
          containerType,
          temperatureMinC: parseFloat(temperatureMinC),
          temperatureMaxC: parseFloat(temperatureMaxC),
          idempotencyKey: newIdempotencyKey(),
        },
      );
      setSubmitResult(data);
    } catch (err) {
      const e2 = err as ApiError;
      setSubmitError(e2.error || "Unable to create request");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="request-page">
      <h1>New collection request</h1>
      <form className="request-form" onSubmit={onSubmit}>
        <fieldset>
          <legend>Origin</legend>
          <label htmlFor="originType">Origin type</label>
          <select
            id="originType"
            value={originType}
            onChange={(e) => setOriginType(e.target.value)}
          >
            {ORIGIN_TYPES.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
          {originType === "node" && (
            <>
              <label htmlFor="originNodeId">Origin node ID</label>
              <input
                id="originNodeId"
                value={originNodeId}
                onChange={(e) => setOriginNodeId(e.target.value)}
              />
            </>
          )}
          <label htmlFor="latitude">Latitude</label>
          <input
            id="latitude"
            value={latitude}
            onChange={(e) => setLatitude(e.target.value)}
            required
          />
          <label htmlFor="longitude">Longitude</label>
          <input
            id="longitude"
            value={longitude}
            onChange={(e) => setLongitude(e.target.value)}
            required
          />
        </fieldset>

        <fieldset>
          <legend>Sample</legend>
          <label htmlFor="sampleTypeId">Sample type ID</label>
          <input
            id="sampleTypeId"
            value={sampleTypeId}
            onChange={(e) => setSampleTypeId(e.target.value)}
            placeholder="UUID provided by your administrator"
            required
          />
          <label htmlFor="containerType">Container type</label>
          <input
            id="containerType"
            value={containerType}
            onChange={(e) => setContainerType(e.target.value)}
            required
          />
          <label htmlFor="temperatureMinC">Temperature min (°C)</label>
          <input
            id="temperatureMinC"
            type="number"
            value={temperatureMinC}
            onChange={(e) => setTemperatureMinC(e.target.value)}
            required
          />
          <label htmlFor="temperatureMaxC">Temperature max (°C)</label>
          <input
            id="temperatureMaxC"
            type="number"
            value={temperatureMaxC}
            onChange={(e) => setTemperatureMaxC(e.target.value)}
            required
          />
        </fieldset>

        <fieldset>
          <legend>Timing</legend>
          <label htmlFor="earliestCollectionAt">Earliest collection at</label>
          <input
            id="earliestCollectionAt"
            type="datetime-local"
            value={earliestCollectionAt}
            onChange={(e) => setEarliestCollectionAt(e.target.value)}
            required
          />
          <label htmlFor="latestCollectionAt">Latest collection at</label>
          <input
            id="latestCollectionAt"
            type="datetime-local"
            value={latestCollectionAt}
            onChange={(e) => setLatestCollectionAt(e.target.value)}
            required
          />
          <label htmlFor="deliveryDeadline">Delivery deadline</label>
          <input
            id="deliveryDeadline"
            type="datetime-local"
            value={deliveryDeadline}
            onChange={(e) => setDeliveryDeadline(e.target.value)}
            required
          />
        </fieldset>

        <div className="form-actions">
          <button type="button" disabled={checking} onClick={onCheck}>
            {checking ? "Checking…" : "Check serviceability"}
          </button>
          <button type="submit" disabled={submitting}>
            {submitting ? "Submitting…" : "Create request"}
          </button>
        </div>

        {checkError && <p role="alert">{checkError}</p>}
        {checkResult && (
          <div
            className={`banner ${
              checkResult.serviceable ? "banner-success" : "banner-warning"
            }`}
            role="status"
          >
            <strong>
              {checkResult.serviceable ? "Serviceable" : "Not serviceable"}
            </strong>
            <p>Reason: {checkResult.reason}</p>
            {checkResult.estimatedArrivalAt && (
              <p>
                Estimated arrival:{" "}
                {new Date(checkResult.estimatedArrivalAt).toLocaleString()}
              </p>
            )}
            <p className="hint">
              This is a dry run only — no request has been created.
            </p>
          </div>
        )}

        {submitError && <p role="alert">{submitError}</p>}
        {submitResult && (
          <div className="banner banner-success" role="status">
            <p>Request created: {submitResult.requestId}</p>
            <p>Sample: {submitResult.sampleId}</p>
            <p>Serviceability: {submitResult.serviceability}</p>
            <button
              type="button"
              onClick={() => navigate(`/samples/${submitResult.sampleId}`)}
            >
              View sample
            </button>
          </div>
        )}
      </form>
    </div>
  );
}

