import { useCallback, useEffect, useState } from "react";
import { api, newIdempotencyKey } from "../api";
import type { ApiError } from "../api";
import type { OperationsState } from "../types";

const RESOURCE_TYPES = [
  "location",
  "node",
  "laboratory",
  "connection",
  "route",
  "worker",
  "capacity",
];

export default function MonitorPage() {
  const [state, setState] = useState<OperationsState | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const [journeyId, setJourneyId] = useState("");
  const [planVersion, setPlanVersion] = useState("1");
  const [reason, setReason] = useState("");
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionResult, setActionResult] = useState<string | null>(null);

  const [resourceType, setResourceType] = useState(RESOURCE_TYPES[0]);
  const [resourceId, setResourceId] = useState("");

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api.post<OperationsState>("/read-operations-state", {});
      setState(data);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to load operations state");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
    const id = setInterval(load, 20000);
    return () => clearInterval(id);
  }, [load]);

  async function onReroute() {
    setActionError(null);
    setActionResult(null);
    try {
      const data = await api.post<{ journeyId: string; replanStatus: string }>(
        "/reroute-journey",
        {
          journeyId,
          expectedPlanVersion: parseInt(planVersion, 10),
          reason: reason || undefined,
          idempotencyKey: newIdempotencyKey(),
        },
      );
      setActionResult(`Reroute status: ${data.replanStatus}`);
      load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to reroute journey");
    }
  }

  async function onCancel() {
    setActionError(null);
    setActionResult(null);
    try {
      const data = await api.post<{ status: string }>("/cancel-journey", {
        journeyId,
        expectedPlanVersion: parseInt(planVersion, 10),
        reason: reason || undefined,
        idempotencyKey: newIdempotencyKey(),
      });
      setActionResult(`Journey ${data.status}`);
      load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to cancel journey");
    }
  }

  async function onReportDisruption() {
    setActionError(null);
    setActionResult(null);
    try {
      const data = await api.post<{ replanStatus: string }>(
        "/report-disruption",
        {
          resourceType,
          resourceId,
          reason: reason || undefined,
          occurredAt: new Date().toISOString(),
          idempotencyKey: newIdempotencyKey(),
        },
      );
      setActionResult(`Replan status: ${data.replanStatus}`);
      load();
    } catch (err) {
      const e2 = err as ApiError;
      setActionError(e2.error || "Unable to report disruption");
    }
  }

  if (loading) return <p>Loading operations…</p>;
  if (error) return <p role="alert">{error}</p>;
  if (!state) return null;

  return (
    <div className="monitor-page">
      <h1>Dispatch monitor</h1>
      <div className="monitor-grid">
        <section aria-labelledby="samples-heading">
          <h2 id="samples-heading">Samples ({state.samples.length})</h2>
          <ul className="monitor-list">
            {state.samples.map((s) => (
              <li key={s.sampleId}>
                <strong>{s.sampleId}</strong> — {s.status}{" "}
                {s.locationStale && <span className="badge badge-stale">stale</span>}
                <div className="muted">Holder: {s.currentHolderId || "—"}</div>
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="workers-heading">
          <h2 id="workers-heading">Workers ({state.workers.length})</h2>
          <ul className="monitor-list">
            {state.workers.map((w) => (
              <li key={w.workerId}>
                <strong>{w.fullName || w.workerId}</strong> — {w.status}{" "}
                <span className="muted">
                  ({w.assignmentCount} assignments, {w.roles.join(", ")})
                </span>
                {w.locationStale && <span className="badge badge-stale">stale</span>}
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="locations-heading">
          <h2 id="locations-heading">Nodes &amp; laboratories ({state.locations.length})</h2>
          <ul className="monitor-list">
            {state.locations.map((l) => (
              <li key={l.id}>
                <strong>{l.name}</strong> — {l.active ? "active" : "inactive"}
                <div className="muted">
                  Regular {l.capacity?.availableUnits}/{l.capacity?.capacityUnits} · Cooled{" "}
                  {l.capacity?.cooledAvailableUnits}/{l.capacity?.cooledCapacityUnits}
                </div>
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="connections-heading">
          <h2 id="connections-heading">Routes ({state.connections.length})</h2>
          <ul className="monitor-list">
            {state.connections.map((c) => (
              <li key={c.id}>
                {c.fromLocationId} → {c.toLocationId} — {c.active ? "active" : "inactive"}
              </li>
            ))}
          </ul>
        </section>

        <section aria-labelledby="exceptions-heading">
          <h2 id="exceptions-heading">Exceptions ({state.exceptions.length})</h2>
          <ul className="monitor-list">
            {state.exceptions.map((e, i) => (
              <li key={i}>{JSON.stringify(e)}</li>
            ))}
          </ul>
        </section>
      </div>

      <section aria-labelledby="replan-heading" className="replan-panel">
        <h2 id="replan-heading">Replan &amp; disruption tools</h2>
        {actionError && <p role="alert">{actionError}</p>}
        {actionResult && <p role="status">{actionResult}</p>}
        <div className="replan-form">
          <label htmlFor="journeyId">Journey ID</label>
          <input id="journeyId" value={journeyId} onChange={(e) => setJourneyId(e.target.value)} />
          <label htmlFor="planVersion">Expected plan version</label>
          <input
            id="planVersion"
            type="number"
            min={1}
            value={planVersion}
            onChange={(e) => setPlanVersion(e.target.value)}
          />
          <label htmlFor="reason">Reason</label>
          <input id="reason" value={reason} onChange={(e) => setReason(e.target.value)} />
          <div className="form-actions">
            <button type="button" onClick={onReroute}>
              Reroute journey
            </button>
            <button type="button" onClick={onCancel}>
              Cancel journey
            </button>
          </div>
        </div>
        <div className="replan-form">
          <label htmlFor="resourceType">Disrupted resource type</label>
          <select id="resourceType" value={resourceType} onChange={(e) => setResourceType(e.target.value)}>
            {RESOURCE_TYPES.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
          <label htmlFor="resourceId">Resource ID</label>
          <input id="resourceId" value={resourceId} onChange={(e) => setResourceId(e.target.value)} />
          <button type="button" onClick={onReportDisruption}>
            Report disruption
          </button>
        </div>
      </section>
    </div>
  );
}

