package server

import (
        "net/http"
        "time"
)

type readOpsStateReq struct {
        Filters map[string]interface{} `json:"filters"`
}

func (s *Server) HandleReadOperationsState(w http.ResponseWriter, r *http.Request) {
        u := RequireRole(w, r, RoleDispatcher, RoleAdministrator)
        if u == nil {
                return
        }
        var req readOpsStateReq
        _ = DecodeJSON(w, r, &req)

        samples := []map[string]interface{}{}
        rows, err := s.DB.Query(r.Context(), `SELECT sam.id, sam.status, req.id, req.origin_lat, req.origin_lon, req.delivery_deadline,
                sam.current_holder_id, sam.active_journey_id, sam.latest_lat, sam.latest_lon, sam.location_recorded_at
                FROM samples sam JOIN requests req ON req.id = sam.request_id`)
        if err == nil {
                defer rows.Close()
                for rows.Next() {
                        var sampleID, status, requestID string
                        var olat, olon float64
                        var deadline time.Time
                        var holder, journeyID *string
                        var latLat, latLon *float64
                        var locRec *time.Time
                        if rows.Scan(&sampleID, &status, &requestID, &olat, &olon, &deadline, &holder, &journeyID, &latLat, &latLon, &locRec) != nil {
                                continue
                        }
                        stale := locRec == nil || time.Since(*locRec) > 30*time.Minute
                        m := map[string]interface{}{
                                "sampleId": sampleID, "status": status, "requestId": requestID,
                                "origin": map[string]interface{}{"latitude": olat, "longitude": olon},
                                "deliveryDeadline": deadline.Format(time.RFC3339), "locationStale": stale,
                        }
                        if holder != nil {
                                m["currentHolderId"] = *holder
                        }
                        if journeyID != nil {
                                m["activeJourneyId"] = *journeyID
                        }
                        if latLat != nil && latLon != nil {
                                m["latestLocation"] = map[string]interface{}{"latitude": *latLat, "longitude": *latLon}
                        }
                        if locRec != nil {
                                m["locationRecordedAt"] = locRec.Format(time.RFC3339)
                        }
                        samples = append(samples, m)
                }
        }

        workers := []map[string]interface{}{}
        wrows, err := s.DB.Query(r.Context(), `SELECT id, full_name, roles, active, recent_assignment_count FROM users
                WHERE roles && ARRAY['collection_professional','delivery_partner','node_handler','laboratory_team']::text[]`)
        if err == nil {
                defer wrows.Close()
                for wrows.Next() {
                        var id string
                        var fullName *string
                        var roles []string
                        var active bool
                        var count int
                        if wrows.Scan(&id, &fullName, &roles, &active, &count) != nil {
                                continue
                        }
                        var latLat, latLon *float64
                        var recAt *time.Time
                        _ = s.DB.QueryRow(r.Context(), `SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id=$1 ORDER BY sequence DESC, id DESC LIMIT 1`, id).Scan(&latLat, &latLon, &recAt)
                        stale := recAt == nil || time.Since(*recAt) > 30*time.Minute
                        status := "unavailable"
                        if active {
                                status = "available"
                        }
                        m := map[string]interface{}{
                                "workerId": id, "roles": roles, "available": active, "status": status,
                                "capacityUnits": count, "assignmentCount": count, "locationStale": stale,
                        }
                        if fullName != nil {
                                m["fullName"] = *fullName
                        }
                        if latLat != nil && latLon != nil {
                                m["latestLocation"] = map[string]interface{}{"latitude": *latLat, "longitude": *latLon}
                        }
                        if recAt != nil {
                                m["locationRecordedAt"] = recAt.Format(time.RFC3339)
                        }
                        workers = append(workers, m)
                }
        }

        locations := []map[string]interface{}{}
        lrows, err := s.DB.Query(r.Context(), `SELECT id, name, latitude, longitude, active, coverage_km, handling_minutes,
                is_collection_point, is_transfer_point, is_hub, is_laboratory FROM locations`)
        if err == nil {
                defer lrows.Close()
                for lrows.Next() {
                        var id, name string
                        var lat, lon, coverage float64
                        var handling int
                        var active, cp, tp, hub, lab bool
                        if lrows.Scan(&id, &name, &lat, &lon, &active, &coverage, &handling, &cp, &tp, &hub, &lab) != nil {
                                continue
                        }
                        cap, _ := s.getOrCreateCapacity(r.Context(), "location", id)
                        m := map[string]interface{}{
                                "id": id, "locationId": id, "name": name, "coordinate": map[string]interface{}{"latitude": lat, "longitude": lon},
                                "active": active, "coverageKm": coverage, "handlingMinutes": handling,
                                "functions": map[string]interface{}{"collection_point": cp, "transfer_point": tp, "hub": hub, "laboratory": lab},
                                "capacity": map[string]interface{}{
                                        "capacityUnits": cap.CapacityUnits, "reservedUnits": cap.ReservedUnits, "availableUnits": cap.AvailableUnits,
                                        "cooledCapacityUnits": cap.CooledCapacityUnits, "cooledReservedUnits": cap.CooledReservedUnits, "cooledAvailableUnits": cap.CooledAvailable,
                                },
                        }
                        locations = append(locations, m)
                }
        }

        connections := []map[string]interface{}{}
        crows, err := s.DB.Query(r.Context(), `SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
        if err == nil {
                defer crows.Close()
                for crows.Next() {
                        var id, from, to string
                        var minutes int
                        var cost float64
                        var cooled, active bool
                        if crows.Scan(&id, &from, &to, &minutes, &cost, &cooled, &active) != nil {
                                continue
                        }
                        cap, _ := s.getOrCreateCapacity(r.Context(), "connection", id)
                        connections = append(connections, map[string]interface{}{
                                "id": id, "connectionId": id, "fromLocationId": from, "toLocationId": to,
                                "travelMinutes": minutes, "costUnits": cost, "cooled": cooled, "active": active,
                                "capacity": map[string]interface{}{
                                        "capacityUnits": cap.CapacityUnits, "reservedUnits": cap.ReservedUnits, "availableUnits": cap.AvailableUnits,
                                        "cooledCapacityUnits": cap.CooledCapacityUnits, "cooledReservedUnits": cap.CooledReservedUnits, "cooledAvailableUnits": cap.CooledAvailable,
                                },
                        })
                }
        }

        exceptions := []map[string]interface{}{}
        erows, err := s.DB.Query(r.Context(), `SELECT id, exception FROM samples WHERE status='exception'`)
        if err == nil {
                defer erows.Close()
                for erows.Next() {
                        var id string
                        var exc []byte
                        if erows.Scan(&id, &exc) != nil {
                                continue
                        }
                        exceptions = append(exceptions, map[string]interface{}{"sampleId": id, "exception": rawJSONOrEmpty(exc)})
                }
        }

        routes := []map[string]interface{}{}
        jrows, err := s.DB.Query(r.Context(), `SELECT id, status, route_mode, plan_version, sample_ids FROM journeys WHERE status NOT IN ('cancelled','merged','superseded')`)
        if err == nil {
                defer jrows.Close()
                for jrows.Next() {
                        var id, status, mode string
                        var version int
                        var sids []string
                        if jrows.Scan(&id, &status, &mode, &version, &sids) != nil {
                                continue
                        }
                        routes = append(routes, map[string]interface{}{"journeyId": id, "status": status, "routeMode": mode, "planVersion": version, "sampleIds": sids})
                }
        }

        WriteData(w, http.StatusOK, map[string]interface{}{
                "samples": samples, "workers": workers, "locations": locations, "connections": connections,
                "exceptions": exceptions, "routes": routes,
        })
}

