import { useState } from "react";
import { api } from "../api";
import type { ApiError } from "../api";

const FUNCTIONS = ["collection_point", "transfer_point", "hub", "laboratory"];

export default function AdminNetworkPage() {
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  const [locName, setLocName] = useState("");
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");
  const [coverageKm, setCoverageKm] = useState("5");
  const [handlingMinutes, setHandlingMinutes] = useState("15");
  const [functions, setFunctions] = useState<string[]>([]);
  const [locActive, setLocActive] = useState(true);

  const [fromLocationId, setFromLocationId] = useState("");
  const [toLocationId, setToLocationId] = useState("");
  const [travelMinutes, setTravelMinutes] = useState("30");
  const [costUnits, setCostUnits] = useState("1");
  const [cooled, setCooled] = useState(false);
  const [connActive, setConnActive] = useState(true);

  const [statusLocationId, setStatusLocationId] = useState("");
  const [statusFunction, setStatusFunction] = useState(FUNCTIONS[0]);
  const [statusConnectionId, setStatusConnectionId] = useState("");

  const [labId, setLabId] = useState("");
  const [labSampleTypeId, setLabSampleTypeId] = useState("");
  const [labAccepts, setLabAccepts] = useState(true);

  function toggleFn(fn: string) {
    setFunctions((prev) => (prev.includes(fn) ? prev.filter((f) => f !== fn) : [...prev, fn]));
  }

  async function onCreateLocation(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      await api.post("/create-location", {
        name: locName,
        coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lon) },
        coverageKm: parseFloat(coverageKm),
        handlingMinutes: parseInt(handlingMinutes, 10),
        active: locActive,
        functions,
      });
      setMessage(`Created location ${locName}`);
      setLocName("");
      setLat("");
      setLon("");
      setFunctions([]);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to create location");
    }
  }

  async function onCreateConnection(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      const data = await api.post<{ connectionId: string }>("/create-connection", {
        fromLocationId,
        toLocationId,
        travelMinutes: parseInt(travelMinutes, 10),
        costUnits: parseFloat(costUnits),
        cooled,
        active: connActive,
      });
      setMessage(`Created connection ${data.connectionId}`);
      setFromLocationId("");
      setToLocationId("");
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to create connection");
    }
  }

  async function onSetLocationStatus(active: boolean) {
    setError(null);
    setMessage(null);
    try {
      await api.post("/set-location-status", { locationId: statusLocationId, active });
      setMessage(`Location ${statusLocationId} set ${active ? "active" : "inactive"}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to set location status");
    }
  }

  async function onSetFunctionStatus(active: boolean) {
    setError(null);
    setMessage(null);
    try {
      await api.post("/set-location-function-status", {
        locationId: statusLocationId,
        function: statusFunction,
        active,
      });
      setMessage(`Function ${statusFunction} set ${active ? "active" : "inactive"}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to set function status");
    }
  }

  async function onSetConnectionStatus(active: boolean) {
    setError(null);
    setMessage(null);
    try {
      await api.post("/set-connection-status", { connectionId: statusConnectionId, active });
      setMessage(`Connection ${statusConnectionId} set ${active ? "active" : "inactive"}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to set connection status");
    }
  }

  async function onConfigureLabAcceptance(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      await api.post("/configure-laboratory-acceptance", {
        laboratoryId: labId,
        sampleTypeId: labSampleTypeId,
        accepts: labAccepts,
      });
      setMessage(`Updated acceptance for laboratory ${labId}`);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to configure laboratory acceptance");
    }
  }

  return (
    <div className="admin-network-page">
      <h1>Network configuration</h1>
      {error && <p role="alert">{error}</p>}
      {message && <p role="status">{message}</p>}

      <section aria-labelledby="create-location-heading">
        <h2 id="create-location-heading">Create location</h2>
        <form onSubmit={onCreateLocation} className="stacked-form">
          <label htmlFor="locName">Name</label>
          <input id="locName" value={locName} onChange={(e) => setLocName(e.target.value)} required />
          <label htmlFor="lat">Latitude</label>
          <input id="lat" value={lat} onChange={(e) => setLat(e.target.value)} required />
          <label htmlFor="lon">Longitude</label>
          <input id="lon" value={lon} onChange={(e) => setLon(e.target.value)} required />
          <label htmlFor="coverageKm">Coverage (km)</label>
          <input id="coverageKm" value={coverageKm} onChange={(e) => setCoverageKm(e.target.value)} />
          <label htmlFor="handlingMinutes">Handling minutes</label>
          <input
            id="handlingMinutes"
            value={handlingMinutes}
            onChange={(e) => setHandlingMinutes(e.target.value)}
          />
          <fieldset>
            <legend>Functions</legend>
            {FUNCTIONS.map((fn) => (
              <label key={fn} className="checkbox-label">
                <input type="checkbox" checked={functions.includes(fn)} onChange={() => toggleFn(fn)} />
                {fn}
              </label>
            ))}
          </fieldset>
          <label className="checkbox-label">
            <input type="checkbox" checked={locActive} onChange={(e) => setLocActive(e.target.checked)} />
            Active
          </label>
          <button type="submit">Create location</button>
        </form>
      </section>

      <section aria-labelledby="create-connection-heading">
        <h2 id="create-connection-heading">Create connection</h2>
        <form onSubmit={onCreateConnection} className="stacked-form">
          <label htmlFor="fromLocationId">From location ID</label>
          <input
            id="fromLocationId"
            value={fromLocationId}
            onChange={(e) => setFromLocationId(e.target.value)}
            required
          />
          <label htmlFor="toLocationId">To location ID</label>
          <input
            id="toLocationId"
            value={toLocationId}
            onChange={(e) => setToLocationId(e.target.value)}
            required
          />
          <label htmlFor="travelMinutes">Travel minutes</label>
          <input id="travelMinutes" value={travelMinutes} onChange={(e) => setTravelMinutes(e.target.value)} />
          <label htmlFor="costUnits">Cost units</label>
          <input id="costUnits" value={costUnits} onChange={(e) => setCostUnits(e.target.value)} />
          <label className="checkbox-label">
            <input type="checkbox" checked={cooled} onChange={(e) => setCooled(e.target.checked)} />
            Cooled
          </label>
          <label className="checkbox-label">
            <input type="checkbox" checked={connActive} onChange={(e) => setConnActive(e.target.checked)} />
            Active
          </label>
          <button type="submit">Create connection</button>
        </form>
      </section>

      <section aria-labelledby="status-heading">
        <h2 id="status-heading">Activate / deactivate</h2>
        <div className="stacked-form">
          <label htmlFor="statusLocationId">Location ID</label>
          <input
            id="statusLocationId"
            value={statusLocationId}
            onChange={(e) => setStatusLocationId(e.target.value)}
          />
          <div className="form-actions">
            <button type="button" onClick={() => onSetLocationStatus(true)}>
              Activate location
            </button>
            <button type="button" onClick={() => onSetLocationStatus(false)}>
              Deactivate location
            </button>
          </div>

          <label htmlFor="statusFunction">Function</label>
          <select id="statusFunction" value={statusFunction} onChange={(e) => setStatusFunction(e.target.value)}>
            {FUNCTIONS.map((fn) => (
              <option key={fn} value={fn}>
                {fn}
              </option>
            ))}
          </select>
          <div className="form-actions">
            <button type="button" onClick={() => onSetFunctionStatus(true)}>
              Activate function
            </button>
            <button type="button" onClick={() => onSetFunctionStatus(false)}>
              Deactivate function
            </button>
          </div>

          <label htmlFor="statusConnectionId">Connection ID</label>
          <input
            id="statusConnectionId"
            value={statusConnectionId}
            onChange={(e) => setStatusConnectionId(e.target.value)}
          />
          <div className="form-actions">
            <button type="button" onClick={() => onSetConnectionStatus(true)}>
              Activate connection
            </button>
            <button type="button" onClick={() => onSetConnectionStatus(false)}>
              Deactivate connection
            </button>
          </div>
        </div>
      </section>

      <section aria-labelledby="lab-acceptance-heading">
        <h2 id="lab-acceptance-heading">Laboratory sample-type acceptance</h2>
        <form onSubmit={onConfigureLabAcceptance} className="stacked-form">
          <label htmlFor="labId">Laboratory ID</label>
          <input id="labId" value={labId} onChange={(e) => setLabId(e.target.value)} required />
          <label htmlFor="labSampleTypeId">Sample type ID</label>
          <input
            id="labSampleTypeId"
            value={labSampleTypeId}
            onChange={(e) => setLabSampleTypeId(e.target.value)}
            required
          />
          <label className="checkbox-label">
            <input type="checkbox" checked={labAccepts} onChange={(e) => setLabAccepts(e.target.checked)} />
            Accepts this sample type
          </label>
          <button type="submit">Save acceptance</button>
        </form>
      </section>
    </div>
  );
}

