        <form onSubmit={onCreateLocation} className="stacked-form">
          <label htmlFor="locName">Name</label>
          <input id="locName" value={locName} onChange={(e) => setLocName(e.target.value)} required />
          <label htmlFor="lat">Latitude</label>
          <input id="lat" value={lat} onChange={(e) => setLat(e.target.value)} required />
          <label htmlFor="lon">Longitude</label>
          <input id="lon" value={lon} onChange={(e) => setLon(e.target.value)} required />
          <label htmlFor="coverageKm">Coverage (km)</label>
          <input id="coverageKm" value={coverageKm} onChange={(e) => setCoverageKm(e.target.value)} />
          <label htmlFor="handlingMinutes">Handling minutes</label>
          <input
            id="handlingMinutes"
            value={handlingMinutes}
            onChange={(e) => setHandlingMinutes(e.target.value)}
          />
          <fieldset>
            <legend>Functions</legend>
            {FUNCTIONS.map((fn) => (
              <label key={fn} className="checkbox-label">
                <input type="checkbox" checked={functions.includes(fn)} onChange={() => toggleFn(fn)} />
                {fn}
              </label>
            ))}
          </fieldset>
          <label className="checkbox-label">
            <input type="checkbox" checked={locActive} onChange={(e) => setLocActive(e.target.checked)} />
            Active
          </label>
          <button type="submit">Create location</button>
        </form>
      </section>

      <section aria-labelledby="create-connection-heading">
        <h2 id="create-connection-heading">Create connection</h2>
        <form onSubmit={onCreateConnection} className="stacked-form">
          <label htmlFor="fromLocationId">From location ID</label>
          <input
            id="fromLocationId"
