import { useState } from "react";
import { useAuth } from "../AuthContext";
import { api } from "../api";
import type { ApiError } from "../api";

interface CapacityResult {
  resourceId: string;
  capacityUnits: number;
  cooledCapacityUnits: number;
}

export default function CapacityPage() {
  const { user } = useAuth();
  const [resourceId, setResourceId] = useState("");
  const [capacityUnits, setCapacityUnits] = useState("10");
  const [cooledCapacityUnits, setCooledCapacityUnits] = useState("0");
  const [result, setResult] = useState<CapacityResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    try {
      const data = await api.post<CapacityResult>("/configure-capacity", {
        resourceId,
        capacityUnits: parseInt(capacityUnits, 10),
        cooledCapacityUnits: parseInt(cooledCapacityUnits, 10),
      });
      setResult(data);
    } catch (err) {
      const e2 = err as ApiError;
      setError(e2.error || "Unable to configure capacity");
    }
  }

  return (
    <div className="capacity-page">
      <h1>Node / laboratory capacity</h1>
      <p className="muted">
        {user?.activeRole === "administrator"
          ? "As an administrator you may configure capacity for any node, laboratory or connection."
          : "You may configure capacity for the node or laboratory you are assigned to."}
      </p>
      {error && <p role="alert">{error}</p>}
      {result && (
        <p role="status">
          Regular capacity: {result.capacityUnits} · Cooled capacity: {result.cooledCapacityUnits}
        </p>
      )}
      <form onSubmit={onSubmit} className="stacked-form">
        <label htmlFor="resourceId">Node / laboratory / connection ID</label>
        <input id="resourceId" value={resourceId} onChange={(e) => setResourceId(e.target.value)} required />

        <label htmlFor="capacityUnits">Regular capacity units</label>
        <input
          id="capacityUnits"
          type="number"
          min={0}
          value={capacityUnits}
          onChange={(e) => setCapacityUnits(e.target.value)}
          required
        />

        <label htmlFor="cooledCapacityUnits">Cooled capacity units</label>
        <input
          id="cooledCapacityUnits"
          type="number"
          min={0}
          value={cooledCapacityUnits}
          onChange={(e) => setCooledCapacityUnits(e.target.value)}
        />

        <button type="submit">Save capacity</button>
      </form>
    </div>
  );
}

