import { Navigate, Route, Routes } from "react-router-dom";
import type { ReactNode } from "react";
import { useAuth } from "./AuthContext";
import Layout from "./Layout";
import LoginPage from "./pages/LoginPage";
import DashboardPage from "./pages/DashboardPage";
import RequestPage from "./pages/RequestPage";
import SampleDetailPage from "./pages/SampleDetailPage";
import MapPage from "./pages/MapPage";
import MonitorPage from "./pages/MonitorPage";
import AuditPage from "./pages/AuditPage";
import AdminUsersPage from "./pages/AdminUsersPage";
import AdminNetworkPage from "./pages/AdminNetworkPage";
import AdminSampleTypesPage from "./pages/AdminSampleTypesPage";
import CapacityPage from "./pages/CapacityPage";

function RequireAuth({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) return <div className="page-loading">Loading…</div>;
  if (!user) return <Navigate to="/login" replace />;
  return <>{children}</>;
}

export default function App() {
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route
        path="/*"
        element={
          <RequireAuth>
            <Layout />
          </RequireAuth>
        }
      >
        <Route index element={<DashboardPage />} />
        <Route path="request" element={<RequestPage />} />
        <Route path="samples/:sampleId" element={<SampleDetailPage />} />
        <Route path="map" element={<MapPage />} />
        <Route path="monitor" element={<MonitorPage />} />
        <Route path="audit" element={<AuditPage />} />
        <Route path="capacity" element={<CapacityPage />} />
        <Route path="admin/users" element={<AdminUsersPage />} />
        <Route path="admin/network" element={<AdminNetworkPage />} />
        <Route path="admin/sample-types" element={<AdminSampleTypesPage />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Route>
    </Routes>
  );
}

package main

import (
        "context"
        "log"
        "net/http"
        "os"
        "path/filepath"

        "labsample/internal/server"
)

func main() {
        ctx := context.Background()
        s := server.New(ctx)

        if err := server.RunMigrations(ctx, s.DB); err != nil {
                log.Fatalf("migrations: %v", err)
        }
        if err := s.EnsureInitialAdmin(ctx); err != nil {
                log.Fatalf("initial admin: %v", err)
        }
        s.SeedDefaults(ctx)

        mux := http.NewServeMux()
        server.RegisterRoutes(mux, s)

        staticDir := os.Getenv("STATIC_DIR")
        if staticDir == "" {
                staticDir = "./frontend/dist"
        }
        if info, err := os.Stat(staticDir); err == nil && info.IsDir() {
                mux.Handle("/", spaHandler(staticDir))
        }

        handler := s.AuthMiddleware(mux)
        handler = withCORS(handler)

        addr := os.Getenv("LISTEN_ADDR")
        if addr == "" {
                addr = "127.0.0.1:8080"
        }
        log.Printf("listening on %s", addr)
        if err := http.ListenAndServe(addr, handler); err != nil {
                log.Fatal(err)
        }
}

// spaHandler serves the built frontend, falling back to index.html for
// client-side routes so a full-page load of any React Router path works.
func spaHandler(dir string) http.Handler {
        fileServer := http.FileServer(http.Dir(dir))
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
                reqPath := filepath.Join(dir, filepath.Clean(r.URL.Path))
                if info, err := os.Stat(reqPath); err == nil && !info.IsDir() {
                        fileServer.ServeHTTP(w, r)
                        return
                }
                http.ServeFile(w, r, filepath.Join(dir, "index.html"))
        })
}

func withCORS(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
                w.Header().Set("Access-Control-Allow-Origin", "*")
                w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
                w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
                if r.Method == http.MethodOptions {
                        w.WriteHeader(http.StatusNoContent)
                        return
                }
                next.ServeHTTP(w, r)
        })
}

