        Events *EventHub
}

func New(ctx context.Context) *Server {
        dbURL := os.Getenv("DATABASE_URL")
        if dbURL == "" {
                dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
        }
        cfg, err := pgxpool.ParseConfig(dbURL)
        if err != nil {
                log.Fatalf("bad database url: %v", err)
        }
        cfg.MaxConns = 20
        pool, err := pgxpool.NewWithConfig(ctx, cfg)
        if err != nil {
                log.Fatalf("db connect: %v", err)
        }
        s := &Server{
                DB:     pool,
                Mux:    http.NewServeMux(),
                Events: NewEventHub(pool),
        }
        return s
}

func (s *Server) Ping(ctx context.Context) error {
        c, cancel := context.WithTimeout(ctx, 3*time.Second)
        defer cancel()
        return s.DB.Ping(c)
}

package server

import (
        "context"
        "log"
        "os"

        "golang.org/x/crypto/bcrypt"
)

// EnsureInitialAdmin creates the first administrator account from
// ADMIN_USERNAME / ADMIN_PASSWORD when no users exist yet. Safe to call on
// every startup: it never creates a duplicate or removes existing users.
func (s *Server) EnsureInitialAdmin(ctx context.Context) error {
        var count int
        if err := s.DB.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&count); err != nil {
                return err
        }
        if count > 0 {
                return nil
        }
        username := os.Getenv("ADMIN_USERNAME")
        password := os.Getenv("ADMIN_PASSWORD")
        if username == "" || password == "" {
                log.Println("ADMIN_USERNAME/ADMIN_PASSWORD not set; skipping initial admin creation")
                return nil
        }
        hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
        if err != nil {
                return err
        }
        _, err = s.DB.Exec(ctx, `INSERT INTO users (username, password_hash, full_name, roles, active)
                VALUES ($1, $2, $3, ARRAY['administrator'], true)
                ON CONFLICT (username) DO NOTHING`, username, string(hash), "Administrator")
        return err
}

// SeedDefaults ensures the four required sample types exist. Safe to run on
// every startup.
func (s *Server) SeedDefaults(ctx context.Context) {
        defaults := []struct {
                name          string
                requiresCool  bool
                qualification string
        }{
                {"Amber", false, "amber"},
                {"Indigo", false, "indigo"},
                {"Frost", true, "frost"},
                {"Pulse", false, "pulse"},
        }
        for _, d := range defaults {
                _, err := s.DB.Exec(ctx, `INSERT INTO sample_types (name, qualified_collector_required, required_qualification, requires_cooled_route, batching_allowed)
                        VALUES ($1, true, $2, $3, $4)
                        ON CONFLICT (name) DO NOTHING`, d.name, d.qualification, d.requiresCool, d.name != "Pulse")
                if err != nil {
                        log.Printf("seed sample type %s: %v", d.name, err)
                }
        }
}

package server

import (
        "context"
        "embed"
        "sort"

        "github.com/jackc/pgx/v5/pgxpool"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

// RunMigrations applies every .sql file under migrations/ in lexical order.
// Statements use CREATE TABLE IF NOT EXISTS, so re-running is idempotent.
func RunMigrations(ctx context.Context, db *pgxpool.Pool) error {
        entries, err := migrationsFS.ReadDir("migrations")
        if err != nil {
                return err
        }
        names := make([]string, 0, len(entries))
        for _, e := range entries {
                if !e.IsDir() {
                        names = append(names, e.Name())
                }
        }
        sort.Strings(names)
        for _, name := range names {
                b, err := migrationsFS.ReadFile("migrations/" + name)
                if err != nil {
                        return err
                }
                if _, err := db.Exec(ctx, string(b)); err != nil {
                        return err
                }
        }
        return nil
}
